    initialization_error = ValueError(
        "cannot initialize controlled Cargo Fmt execution: "
        + sanitize_private_error(error, private_root)
    )

if initialization_error is not None or pending_signal is not None:
    initialization_mask = None
    try:
        if private_root is not None:
            try:
                shutil.rmtree(private_root)
            except OSError as cleanup_error:
                initialization_error = append_adapter_error(
                    initialization_error,
                    ValueError(f"cannot remove controlled Cargo Fmt directory: {cleanup_error}"),
                )
        try:
            initialization_mask = signal.pthread_sigmask(
                signal.SIG_BLOCK, handled_signals
            )
        except (OSError, ValueError) as mask_error:
            initialization_error = append_adapter_error(
                initialization_error,
                ValueError(f"cannot block initialization cleanup signals: {mask_error}"),
            )
        initialization_error = apply_pending_signal(initialization_error)
        if initialization_mask is not None:
            initialization_error, _ = drain_blocked_signals(initialization_error)
    finally:
        for signum, handler in previous_handlers.items():
            try:
                signal.signal(signum, handler)
            except (OSError, ValueError):
                pass
        cleaning = False
    fail(sanitize_private_error(initialization_error, private_root))
cleaning = False

coverage_workspace = os.path.join(private_root, "coverage-workspace")
coverage_manifest = os.path.join(coverage_workspace, "Cargo.toml")
coverage_config_directory = coverage_workspace if root_configs else config_directory

def metadata_arguments(selected_manifest):
    return [
        cargo,
        "metadata",
        "--format-version=1",
        "--no-deps",
        "--manifest-path",
        selected_manifest,
        "--locked",
        "--offline",
        "--quiet",
    ]

def format_arguments(selected_manifest, selected_config, check):
    arguments = [cargo_fmt, "fmt", "--all", "--manifest-path", selected_manifest]
    if check:
        arguments.append("--check")
    arguments.extend(
        ["--", "--config-path", selected_config, "--color", "never", "--files-with-diff"]
    )
    return arguments

metadata_args = metadata_arguments(manifest)
coverage_metadata_args = metadata_arguments(coverage_manifest)
coverage_args = format_arguments(coverage_manifest, coverage_config_directory, True)
format_args = format_arguments(manifest, config_directory, phase == "verify")

def run_child(arguments):
    global process
    global cleaning
    stdout_chunks = []
    stderr_chunks = []
    total = 0
    process = subprocess.Popen(
        arguments,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        cwd=invocation_dir,
        env=environment,
        start_new_session=True,
    )
    selector = selectors.DefaultSelector()
    for stream, chunks in ((process.stdout, stdout_chunks), (process.stderr, stderr_chunks)):
        if stream is None:
            raise OSError("failed to capture Cargo Fmt output")
        os.set_blocking(stream.fileno(), False)
        selector.register(stream, selectors.EVENT_READ, chunks)
    while selector.get_map():
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        for key, _ in selector.select(timeout=0.1):
            chunk = os.read(key.fileobj.fileno(), 65536)
            if chunk:
                total += len(chunk)
                if total > OUTPUT_LIMIT:
                    raise BufferError(f"combined output exceeded {OUTPUT_LIMIT} bytes")
                key.data.append(chunk)
            else:
                selector.unregister(key.fileobj)
                key.fileobj.close()
    status = process.wait()
    cleaning = True
    try:
        left_descendants = sweep_process_group()
    finally:
        cleaning = False
    if left_descendants:
        raise ValueError("child left same-group descendants after leader exit")
    process = None
    if pending_signal is not None:
        raise AdapterSignal(pending_signal)
    return status, b"".join(stdout_chunks), b"".join(stderr_chunks)

def assert_snapshot_unchanged(
    before, before_directories, after, after_directories, context
):
    if set(before) != set(after):
        raise ValueError(f"{context} changed workspace paths")
    for relative, snapshot in before.items():
        current = after[relative]
        for key in ("device", "inode", "mode", "mtime", "sha256", "size"):
            if current[key] != snapshot[key]:
                raise ValueError(f"{context} changed {relative}")
    if set(before_directories) != set(after_directories):
        raise ValueError(f"{context} changed workspace directory topology")
    for relative, snapshot in before_directories.items():
        if after_directories[relative]["mode"] != snapshot["mode"]:
            raise ValueError(f"{context} changed directory {relative}")

def parse_metadata(raw, selected_workspace, selected_manifests, selected_sources):
    try:
        metadata = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ValueError(f"Cargo metadata is not one UTF-8 JSON object: {error}")
    if not isinstance(metadata, dict) or metadata.get("version") != 1:
        raise ValueError("Cargo metadata does not use the locked version-1 schema")
    metadata_root = metadata.get("workspace_root")
    if not isinstance(metadata_root, str) or os.path.realpath(metadata_root) != selected_workspace:
        raise ValueError("Cargo workspace root differs from the selected Cargo.toml directory")
    target_directory = metadata.get("target_directory")
    if not isinstance(target_directory, str) or os.path.realpath(target_directory) != private_root:
        raise ValueError("Cargo metadata ignored the controlled target directory")
    build_directory = metadata.get("build_directory")
    if not isinstance(build_directory, str) or os.path.realpath(build_directory) != private_root:
        raise ValueError("Cargo metadata ignored the controlled build directory")
    members = metadata.get("workspace_members")
    packages = metadata.get("packages")
    if not isinstance(members, list) or not members or len(set(members)) != len(members):
        raise ValueError("Cargo metadata has no unique workspace-member set")
    if not isinstance(packages, list) or len(packages) != len(members):
        raise ValueError("Cargo metadata must contain exactly the workspace packages")
    member_ids = set(members)
    package_ids = {package.get("id") for package in packages if isinstance(package, dict)}
    if package_ids != member_ids:
        raise ValueError("Cargo package records differ from workspace members")
    member_manifests = set()
    target_sources = set()
    for package in packages:
        package_manifest = package.get("manifest_path")
        if not isinstance(package_manifest, str):
            raise ValueError("Cargo package manifest path is missing")
        package_manifest = os.path.abspath(package_manifest)
        if os.path.realpath(package_manifest) != package_manifest:
            raise ValueError("Cargo package manifest path is not canonical")
        try:
            inside = os.path.commonpath((selected_workspace, package_manifest)) == selected_workspace
        except ValueError:
            inside = False
        relative_manifest = os.path.relpath(package_manifest, selected_workspace).replace(os.sep, "/")
        if not inside or relative_manifest not in selected_manifests:
            raise ValueError(f"Cargo package manifest escapes the validated workspace: {package_manifest}")
        member_manifests.add(relative_manifest)
        dependencies = package.get("dependencies")
        if not isinstance(dependencies, list):
            raise ValueError("Cargo package dependencies are missing")
        for dependency in dependencies:
            if not isinstance(dependency, dict):
                raise ValueError("Cargo dependency record is malformed")
            dependency_path = dependency.get("path")
            if dependency_path is None:
                continue
            if not isinstance(dependency_path, str):
                raise ValueError("Cargo path dependency is malformed")
            dependency_manifest = os.path.join(os.path.realpath(dependency_path), "Cargo.toml")
            try:
                dependency_inside = (
                    os.path.commonpath((selected_workspace, dependency_manifest)) == selected_workspace
                )
            except ValueError:
                dependency_inside = False
            dependency_relative = os.path.relpath(dependency_manifest, selected_workspace).replace(os.sep, "/")
            if not dependency_inside or dependency_relative not in selected_manifests:
                raise ValueError(f"Cargo path dependency escapes the workspace: {dependency_path}")
        targets = package.get("targets")
        if not isinstance(targets, list) or not targets:
            raise ValueError("Cargo workspace package has no targets")
        for target in targets:
            source = target.get("src_path") if isinstance(target, dict) else None
            if not isinstance(source, str):
                raise ValueError("Cargo target source path is missing")
            source = os.path.abspath(source)
            if os.path.realpath(source) != source:
                raise ValueError(f"Cargo target source is not canonical: {source}")
            relative = os.path.relpath(source, selected_workspace).replace(os.sep, "/")
            if relative not in selected_sources:
                raise ValueError(f"Cargo target source escapes physical Rust scope: {source}")
            target_sources.add(relative)
    allowed_manifests = member_manifests.union({"Cargo.toml"})
    if selected_manifests != allowed_manifests:
        unsupported = ", ".join(sorted(selected_manifests - allowed_manifests))
        raise ValueError(f"non-member Cargo manifests are unsupported: {unsupported}")
    for package in packages:
        for dependency in package["dependencies"]:
            dependency_path = dependency.get("path")
            if dependency_path is None:
                continue
            dependency_manifest = os.path.join(os.path.realpath(dependency_path), "Cargo.toml")
            dependency_relative = os.path.relpath(dependency_manifest, selected_workspace).replace(os.sep, "/")
            if dependency_relative not in member_manifests:
                raise ValueError(f"non-member Cargo path dependency is unsupported: {dependency_path}")
    return len(packages), sorted(target_sources)

def parse_report(raw, selected_workspace, selected_sources):
    try:
        text = raw.decode("utf-8")
    except UnicodeError as error:
        raise ValueError(f"rustfmt files-with-diff output is not UTF-8: {error}")
    reported = []
    for line in text.splitlines():
        if not line or line != line.strip():
            raise ValueError("rustfmt files-with-diff output has a non-canonical line")
        path = line if os.path.isabs(line) else os.path.join(invocation_dir, line)
        path = os.path.abspath(path)
        if os.path.realpath(path) != path:
            raise ValueError(f"rustfmt reported a non-canonical path: {line}")
        relative = os.path.relpath(path, selected_workspace).replace(os.sep, "/")
        if relative not in selected_sources:
            raise ValueError(f"rustfmt reported a path outside physical Rust scope: {line}")
        if relative in reported:
            raise ValueError(f"rustfmt reported a duplicate path: {relative}")
        reported.append(relative)
    return sorted(reported)

def sanitize_private_output(output):
    return output.replace(os.fsencode(private_root), b"<cargo-fmt-private>")

def workspace_diff(before, before_directories, after, after_directories):
    before_paths = set(before)
    after_paths = set(after)
    added = sorted(after_paths - before_paths)
    removed = sorted(before_paths - after_paths)
    changed = sorted(
        relative
        for relative in before_paths.intersection(after_paths)
        if before[relative]["content"] != after[relative]["content"]
    )
    touched = sorted(
        relative
        for relative in before_paths.intersection(after_paths)
        if before[relative]["mode"] != after[relative]["mode"]
        or (
            relative not in changed
            and any(
                before[relative][key] != after[relative][key]
                for key in ("device", "inode", "mtime", "size", "sha256")
            )
        )
    )
    before_directory_paths = set(before_directories)
    after_directory_paths = set(after_directories)
    added_directories = sorted(after_directory_paths - before_directory_paths)
    removed_directories = sorted(before_directory_paths - after_directory_paths)
    touched_directories = sorted(
        relative
        for relative in before_directory_paths.intersection(after_directory_paths)
        if before_directories[relative]["mode"] != after_directories[relative]["mode"]
    )
    return (
        added,
        removed,
        changed,
        touched,
        added_directories,
        removed_directories,
        touched_directories,
    )

def atomic_write(path, content, mode):
    descriptor, temporary_path = tempfile.mkstemp(prefix=".velvet-glove-cargo-fmt-", dir=os.path.dirname(path))
    try:
        os.fchmod(descriptor, mode)
        with os.fdopen(descriptor, "wb", closefd=True) as output:
            descriptor = -1
            output.write(content)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary_path, path)
    except BaseException:
        if descriptor >= 0:
            os.close(descriptor)
        try:
            os.unlink(temporary_path)
        except OSError:
            pass
        raise

def set_directory_mode(path, mode, expected=None):
    descriptor = os.open(
        path,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        opened = os.fstat(descriptor)
        if not stat.S_ISDIR(opened.st_mode):
            raise ValueError(f"path is not a real directory: {path}")
        if expected is not None and (
            opened.st_dev != expected["device"] or opened.st_ino != expected["inode"]
        ):
            raise ValueError(f"directory changed before restoring its mode: {path}")
        os.fchmod(descriptor, mode)
        restored = os.fstat(descriptor)
        if (
            restored.st_dev != opened.st_dev
            or restored.st_ino != opened.st_ino
            or stat.S_IMODE(restored.st_mode) != mode
        ):
            raise ValueError(f"directory changed while restoring its mode: {path}")
    finally:
        os.close(descriptor)

def create_coverage_workspace():
    os.mkdir(coverage_workspace, mode=0o700)
    for relative in sorted(
        baseline_directories,
        key=lambda item: (item.count("/"), item),
    ):
        if relative == ".":
            continue
        destination = os.path.join(coverage_workspace, relative.replace("/", os.sep))
        os.mkdir(destination, mode=0o700)
    probe = b"\nconst _: ()=();\n"
    for relative, snapshot in sorted(baseline.items()):
        destination = os.path.join(coverage_workspace, relative.replace("/", os.sep))
        content = snapshot["content"]
        if relative in source_snapshots:
            content += probe
        descriptor = os.open(
            destination,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
            snapshot["mode"],
        )
        try:
            os.fchmod(descriptor, snapshot["mode"])
            with os.fdopen(descriptor, "wb", closefd=True) as output:
                descriptor = -1
                output.write(content)
                output.flush()
                os.fsync(output.fileno())
        finally:
            if descriptor >= 0:
                os.close(descriptor)
    for relative in sorted(
        baseline_directories,
        key=lambda item: (item.count("/"), item),
        reverse=True,
    ):
        destination = (
            coverage_workspace
            if relative == "."
            else os.path.join(coverage_workspace, relative.replace("/", os.sep))
        )
        set_directory_mode(destination, baseline_directories[relative]["mode"])

def restore_workspace(before, before_directories):
    errors = []

    def directory_path(relative):
        return (
            workspace
            if relative == "."
            else os.path.join(workspace, relative.replace("/", os.sep))
        )

    def make_directory_traversable(path):
        initial = os.lstat(path)
        if stat.S_ISLNK(initial.st_mode) or not stat.S_ISDIR(initial.st_mode):
            raise ValueError(f"path is not a real directory: {path}")
        current_mode = stat.S_IMODE(initial.st_mode)
        temporary_mode = current_mode | stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR
        if temporary_mode != current_mode:
            os.chmod(path, temporary_mode, follow_symlinks=False)
            restored = os.lstat(path)
            if (
                stat.S_ISLNK(restored.st_mode)
                or not stat.S_ISDIR(restored.st_mode)
                or restored.st_dev != initial.st_dev
                or restored.st_ino != initial.st_ino
                or stat.S_IMODE(restored.st_mode) != temporary_mode
            ):
                raise ValueError(f"directory changed while making it traversable: {path}")

    if not os.path.lexists(workspace):
        try:
            os.mkdir(workspace, mode=0o700)
        except OSError as error:
            errors.append(f"recreate workspace root: {error}")
    for relative in sorted(
        before_directories,
        key=lambda item: (item.count("/"), item),
    ):
        path = directory_path(relative)
        if not os.path.lexists(path):
            continue
        try:
            make_directory_traversable(path)
        except (OSError, ValueError) as error:
            errors.append(f"make {relative} traversable: {error}")

    def restore_walk_error(error):
        errors.append(f"walk workspace for rollback: {error}")

    for directory, child_directories, _ in os.walk(
        workspace, followlinks=False, onerror=restore_walk_error
    ):
        retained = []
        for name in child_directories:
            if name in SKIPPED_DIRECTORIES:
                continue
            path = os.path.join(directory, name)
            if not os.path.islink(path):
                try:
                    make_directory_traversable(path)
                except (OSError, ValueError) as error:
                    relative = os.path.relpath(path, workspace).replace(os.sep, "/")
                    errors.append(f"make {relative} traversable: {error}")
            retained.append(name)
        child_directories[:] = retained

    try:
        current, _, _, _, current_directories = scan_workspace(require_sources=False)
    except (OSError, ValueError) as error:
        raise ValueError("rollback failed: " + "; ".join(errors + [str(error)]))
    for relative in sorted(set(current) - set(before), reverse=True):
        path = os.path.join(workspace, relative.replace("/", os.sep))
        try:
            os.unlink(path)
        except OSError as error:
            errors.append(f"remove {relative}: {error}")
    for relative in sorted(
        set(current_directories) - set(before_directories),
        key=lambda item: (item.count("/"), item),
        reverse=True,
    ):
        path = directory_path(relative)
        try:
            os.rmdir(path)
        except OSError as error:
            errors.append(f"remove directory {relative}: {error}")
    for relative in sorted(
        set(before_directories) - set(current_directories),
        key=lambda item: (item.count("/"), item),
    ):
        path = directory_path(relative)
        try:
            os.mkdir(path, mode=0o700)
        except OSError as error:
            errors.append(f"recreate directory {relative}: {error}")
    for relative, snapshot in before.items():
        path = os.path.join(workspace, relative.replace("/", os.sep))
        try:
            current_snapshot = file_snapshot(path) if os.path.exists(path) else None
            if (
                current_snapshot is None
                or current_snapshot["content"] != snapshot["content"]
                or current_snapshot["mode"] != snapshot["mode"]
            ):
                os.makedirs(os.path.dirname(path), exist_ok=True)
                atomic_write(path, snapshot["content"], snapshot["mode"])
                current_snapshot = file_snapshot(path)
            if current_snapshot["mtime"] != snapshot["mtime"]:
                descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
                try:
                    opened = os.fstat(descriptor)
                    if (
                        not stat.S_ISREG(opened.st_mode)
                        or opened.st_nlink != 1
                        or opened.st_dev != current_snapshot["device"]
                        or opened.st_ino != current_snapshot["inode"]
                    ):
                        raise ValueError(f"path changed before restoring its mtime: {path}")
                    os.utime(
                        descriptor,
                        ns=(opened.st_atime_ns, snapshot["mtime"]),
                    )
                    restored = os.fstat(descriptor)
                    if (
                        restored.st_dev != opened.st_dev
                        or restored.st_ino != opened.st_ino
                        or restored.st_mtime_ns != snapshot["mtime"]
                    ):
                        raise ValueError(f"path changed while restoring its mtime: {path}")
                finally:
                    os.close(descriptor)
        except (OSError, ValueError) as error:
            errors.append(f"restore {relative}: {error}")
    for relative in sorted(
        before_directories,
        key=lambda item: (item.count("/"), item),
        reverse=True,
    ):
        path = directory_path(relative)
        try:
            current_snapshot = directory_snapshot(path)
            if current_snapshot["mode"] != before_directories[relative]["mode"]:
                set_directory_mode(
                    path,
                    before_directories[relative]["mode"],
                    current_snapshot,
                )
        except (OSError, ValueError) as error:
            errors.append(f"restore directory {relative}: {error}")
    try:
        restored, _, _, _, restored_directories = scan_workspace()
        if set(restored) != set(before):
            errors.append("restored workspace paths differ from the baseline")
        else:
            for relative, snapshot in before.items():
                current_snapshot = restored[relative]
                for key in ("content", "mode", "mtime"):
                    if current_snapshot[key] != snapshot[key]:
                        errors.append(f"restored {relative} {key} differs from the baseline")
        if set(restored_directories) != set(before_directories):
            errors.append("restored workspace directory topology differs from the baseline")
        else:
            for relative, snapshot in before_directories.items():
                if restored_directories[relative]["mode"] != snapshot["mode"]:
                    errors.append(
                        f"restored directory {relative} mode differs from the baseline"
                    )
    except (OSError, ValueError) as error:
        errors.append(f"verify restored workspace: {error}")
    if errors:
        raise ValueError("rollback failed: " + "; ".join(errors))

adapter_error = None
raw_stdout = b""
raw_stderr = b""
summary = None
outer_status = 2
rollback_eligible = False
try:
    raw_stdout = b""
    raw_stderr = b""
    metadata_status, metadata_stdout, metadata_stderr = run_child(metadata_args)
    raw_stdout = metadata_stdout
    raw_stderr = metadata_stderr
    if metadata_status != 0 or metadata_stderr:
        raise ValueError(f"Cargo metadata exited {metadata_status} without clean completion")
    packages, target_sources = parse_metadata(
        metadata_stdout, workspace, physical_manifests, source_snapshots
    )
    after_metadata, _, _, _, after_metadata_directories = scan_workspace()
    assert_snapshot_unchanged(
        baseline,
        baseline_directories,
        after_metadata,
        after_metadata_directories,
        "Cargo metadata",
    )

    # Prove that cargo-fmt actually reaches every physical Rust source. A
    # private copy receives one parseable formatting defect per source; the
    # check must report the complete physical set before the real workspace
    # is trusted. This catches dormant .rs files and Cargo target-selection
    # changes without transiently modifying the selected workspace.
    create_coverage_workspace()
    (
        coverage_baseline,
        coverage_sources,
        coverage_manifests,
        coverage_configs,
        coverage_directories,
    ) = scan_workspace(coverage_workspace)
    if set(coverage_sources) != set(source_snapshots):
        raise ValueError("coverage workspace Rust sources differ from the validated workspace")
    if coverage_manifests != physical_manifests or coverage_configs != rustfmt_configs:
        raise ValueError("coverage workspace Cargo or rustfmt configuration differs from the validated workspace")
    if (
        set(coverage_directories) != set(baseline_directories)
        or any(
            coverage_directories[relative]["mode"]
            != baseline_directories[relative]["mode"]
            for relative in baseline_directories
        )
    ):
        raise ValueError("coverage workspace directory topology or modes differ from the validated workspace")

    raw_stdout = b""
    raw_stderr = b""
    coverage_metadata_status, coverage_metadata_stdout, coverage_metadata_stderr = run_child(
        coverage_metadata_args
    )
    raw_stdout = sanitize_private_output(coverage_metadata_stdout)
    raw_stderr = sanitize_private_output(coverage_metadata_stderr)
    if coverage_metadata_status != 0 or coverage_metadata_stderr:
        raise ValueError(
            f"coverage Cargo metadata exited {coverage_metadata_status} without clean completion"
        )
    coverage_packages, coverage_target_sources = parse_metadata(
        coverage_metadata_stdout,
        coverage_workspace,
        coverage_manifests,
        coverage_sources,
    )
    if coverage_packages != packages or coverage_target_sources != target_sources:
        raise ValueError("coverage Cargo target selection differs from the validated workspace")
    (
        after_coverage_metadata,
        _,
        _,
        _,
        after_coverage_metadata_directories,
    ) = scan_workspace(coverage_workspace)
    assert_snapshot_unchanged(
        coverage_baseline,
        coverage_directories,
        after_coverage_metadata,
        after_coverage_metadata_directories,
        "coverage Cargo metadata",
    )
    (
        after_coverage_metadata_original,
        _,
        _,
        _,
        after_coverage_metadata_original_directories,
    ) = scan_workspace()
    assert_snapshot_unchanged(
        baseline,
        baseline_directories,
        after_coverage_metadata_original,
        after_coverage_metadata_original_directories,
        "coverage Cargo metadata",
    )

    raw_stdout = b""
    raw_stderr = b""
    coverage_status, coverage_stdout, coverage_stderr = run_child(coverage_args)
    raw_stdout = sanitize_private_output(coverage_stdout)
    raw_stderr = sanitize_private_output(coverage_stderr)
    coverage_report = parse_report(
        coverage_stdout, coverage_workspace, coverage_sources
    )
    if coverage_status != 1 or coverage_stderr:
        raise ValueError(
            f"cargo-fmt coverage check exited {coverage_status} without a clean issue report"
        )
    if coverage_report != sorted(source_snapshots):
        missing = sorted(set(source_snapshots) - set(coverage_report))
        unexpected = sorted(set(coverage_report) - set(source_snapshots))
        raise ValueError(
            "cargo-fmt does not cover the complete physical Rust source set: "
            f"missing={missing}, unexpected={unexpected}"
        )
    after_coverage, _, _, _, after_coverage_directories = scan_workspace(
        coverage_workspace
    )
    assert_snapshot_unchanged(
        coverage_baseline,
        coverage_directories,
        after_coverage,
        after_coverage_directories,
        "cargo-fmt coverage check",
    )
    after_coverage_original, _, _, _, after_coverage_original_directories = scan_workspace()
    assert_snapshot_unchanged(
        baseline,
        baseline_directories,
        after_coverage_original,
        after_coverage_original_directories,
        "cargo-fmt coverage check",
    )

    rollback_eligible = True
    raw_stdout = b""
    raw_stderr = b""
    format_status, format_stdout, format_stderr = run_child(format_args)
    raw_stdout = format_stdout
    raw_stderr = format_stderr
    after_format, _, _, _, after_format_directories = scan_workspace()
    (
        added,
        removed,
        changed,
        touched,
        added_directories,
        removed_directories,
        touched_directories,
    ) = workspace_diff(
        baseline,
        baseline_directories,
        after_format,
        after_format_directories,
    )
    reported = parse_report(format_stdout, workspace, source_snapshots)
    if format_stderr:
        raise ValueError("cargo-fmt wrote stderr, so status cannot be classified as a formatting issue")
    if (
        added
        or removed
        or touched
        or added_directories
        or removed_directories
        or touched_directories
    ):
        raise ValueError(
            f"cargo-fmt changed workspace structure or metadata: added={added}, removed={removed}, touched={touched}, added_directories={added_directories}, removed_directories={removed_directories}, touched_directories={touched_directories}"
        )
    non_sources = sorted(set(changed) - set(source_snapshots))
    if non_sources:
        raise ValueError("cargo-fmt changed non-Rust workspace files: " + ", ".join(non_sources))
    if phase == "verify":
        if changed:
            raise ValueError("cargo-fmt check mode mutated workspace files")
        if format_status == 0:
            if reported:
                raise ValueError("clean cargo-fmt check reported unformatted files")
            status_name = "clean"
            outer_status = 0
        elif format_status == 1 and reported:
            status_name = "issues"
            outer_status = 1
        else:
            raise ValueError(f"cargo-fmt check exited {format_status} without a complete issue report")
        changed_report = []
    else:
        if format_status != 0:
            raise ValueError(f"cargo-fmt format exited {format_status}")
        if sorted(changed) != reported:
            raise ValueError(
                f"cargo-fmt changed-file report differs from workspace bytes: report={reported}, changed={changed}"
            )
        status_name = "fixed" if changed else "clean"
        changed_report = changed
        outer_status = 0
    summary = {
        "changed": changed_report,
        "kind": "cargo-fmt",
        "packages": packages,
        "phase": phase,
        "sources": len(source_snapshots),
        "status": status_name,
        "targets": len(target_sources),
        "unformatted": reported if phase == "verify" else [],
    }
except AdapterSignal as error:
    stop_child(error.signum)
    adapter_error = error
    reported_signal = error.signum
except BaseException as error:
    stop_child()
    adapter_error = error
finally:
    cleaning = True
    blocked_mask = None
    try:
        try:
            shutil.rmtree(private_root)
        except OSError as cleanup_error:
            adapter_error = append_adapter_error(
                adapter_error,
                ValueError(f"cannot remove controlled Cargo Fmt directory: {cleanup_error}"),
            )
        try:
            blocked_mask = signal.pthread_sigmask(signal.SIG_BLOCK, handled_signals)
        except (OSError, ValueError) as mask_error:
            adapter_error = append_adapter_error(
                adapter_error, ValueError(f"cannot block cleanup signals: {mask_error}")
            )
        rollback_attempted = False
        while True:
            adapter_error = apply_pending_signal(adapter_error)
            drained = False
            if blocked_mask is not None:
                adapter_error, drained = drain_blocked_signals(adapter_error)
            if adapter_error is not None and rollback_eligible and not rollback_attempted:
                rollback_attempted = True
                try:
                    restore_workspace(baseline, baseline_directories)
                except BaseException as rollback_error:
                    adapter_error = append_adapter_error(adapter_error, rollback_error)
                continue
            if not drained:
                break
        if adapter_error is not None:
            outer_status = 2
    finally:
        try:
            for signum, handler in previous_handlers.items():
                try:
                    signal.signal(signum, handler)
                except (OSError, ValueError):
                    pass
        finally:
            cleaning = False

if adapter_error is not None:
    if raw_stdout:
        sys.stdout.buffer.write(sanitize_private_output(raw_stdout))
    if raw_stderr:
        sys.stderr.buffer.write(sanitize_private_output(raw_stderr))
    fail(sanitize_private_error(adapter_error, private_root))
sys.stdout.write(json.dumps(summary, sort_keys=True, separators=(",", ":")) + "\n")
raise SystemExit(outer_status)

import hashlib
import json
import os
import re
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time

MARKER = "__VELVET_GLOVE_CONTEXTLINT_FILES__"
VERSION = "1.1.1"
MAX_CONFIG_BYTES = 1024 * 1024
MAX_FILE_BYTES = 16 * 1024 * 1024
MAX_TOTAL_BYTES = 64 * 1024 * 1024
MAX_FILES = 4096
MAX_ENTRIES = 100000
MAX_OUTPUT_BYTES = 16 * 1024 * 1024
EXCLUDED_DIRECTORIES = frozenset((".git", "node_modules", ".velvet-glove"))
# glob 13.0.6 expands braces before minimatch 10.2.6 parses a pattern.
# This is minimatch.escape(..., magicalBraces=True)'s POSIX magic set.
GLOB_MAGIC = frozenset("*?()[]{}\\")
RULES = frozenset((
    "tbl001", "tbl002", "tbl003", "tbl004", "tbl005", "tbl006",
    "sec001", "sec002", "str001",
    "ref001", "ref002", "ref003", "ref004", "ref005", "ref006",
    "chk001", "ctx001", "ctx002", "grp001", "grp002", "grp003",
))
PROBE_CONFIG = (
    b'{"rules":[{"rule":"sec001","options":{"sections":'
    b'["__VELVET_GLOVE_CONTEXTLINT_COMPLETION__"]}}]}\n'
)
PROBE_DOCUMENT = b"# Probe\n"
PROBE_REPORT = [{
    "file": "probe.md",
    "line": 0,
    "severity": "error",
    "message": 'Missing required section "__VELVET_GLOVE_CONTEXTLINT_COMPLETION__"',
    "ruleId": "SEC-001",
}]


class AdapterFailure(Exception):
    pass


class AdapterSignal(BaseException):
    def __init__(self, signum):
        super().__init__(f"received signal {signum}")
        self.signum = signum


def reject(message):
    raise AdapterFailure(message)


def reject_glob_magic_path(path, description):
    absolute = os.path.abspath(path)
    for component in absolute.split(os.sep):
        magic = "".join(sorted(set(component).intersection(GLOB_MAGIC)))
        if magic:
            reject(
                f"{description} contains Contextlint glob magic {magic!r}: {path}"
            )


def duplicate_safe_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            reject(f"configuration contains duplicate key {key!r}")
        value[key] = item
    return value


def read_bounded(path, limit, description):
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        before = os.lstat(path)
        if not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(before.st_mode):
            reject(f"{description} is not a regular file: {path}")
        if before.st_nlink != 1:
            reject(f"{description} must have exactly one hard link: {path}")
        descriptor = os.open(path, flags)
        try:
            opened = os.fstat(descriptor)
            if (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino):
                reject(f"{description} changed while opening: {path}")
            chunks = []
            total = 0
            while True:
                chunk = os.read(descriptor, min(65536, limit + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > limit:
                    reject(f"{description} exceeds {limit} bytes: {path}")
        finally:
            os.close(descriptor)
    except AdapterFailure:
        raise
    except OSError as error:
        reject(f"cannot read {description} {path}: {error}")
    data = b"".join(chunks)
    identity = (
        before.st_dev,
        before.st_ino,
        before.st_mode,
        before.st_nlink,
        before.st_size,
        before.st_mtime_ns,
        hashlib.sha256(data).hexdigest(),
    )
    return data, identity


def parse_json_bytes(data, description):
    try:
        text = data.decode("utf-8")
        return json.loads(text, object_pairs_hook=duplicate_safe_object)
    except AdapterFailure:
        raise
    except (UnicodeError, json.JSONDecodeError) as error:
        reject(f"invalid UTF-8 JSON in {description}: {error}")


def resolve_program(name, description):
    if not name or "\x00" in name:
        reject(f"invalid {description} name")
    candidate = shutil.which(name)
    if candidate is None:
        reject(f"cannot resolve {description} {name!r}")
    absolute = os.path.abspath(candidate)
    try:
        metadata = os.stat(absolute)
    except OSError as error:
        reject(f"cannot inspect {description} {absolute}: {error}")
    if not stat.S_ISREG(metadata.st_mode) or not os.access(absolute, os.X_OK):
        reject(f"{description} is not an executable regular file: {absolute}")
    return absolute


def validate_package_graph(tool_program):
    resolved = os.path.realpath(tool_program)
    cursor = os.path.dirname(resolved)
    graph = None
    while True:
        if os.path.basename(cursor) == "node_modules":
            graph = cursor
            break
        parent = os.path.dirname(cursor)
        if parent == cursor:
            break
        cursor = parent
    if graph is None:
        reject(f"contextlint executable is outside a node_modules graph: {tool_program}")
    graph = os.path.realpath(graph)
    cli_entry = os.path.realpath(
        os.path.join(graph, "@contextlint", "cli", "dist", "index.js")
    )
    if resolved != cli_entry:
        reject(
            "contextlint executable does not resolve to "
            f"@contextlint/cli/dist/index.js: {tool_program}"
        )
    cli_manifest_path = os.path.join(graph, "@contextlint", "cli", "package.json")
    core_manifest_path = os.path.join(graph, "@contextlint", "core", "package.json")
    cli_bytes, _ = read_bounded(cli_manifest_path, MAX_CONFIG_BYTES, "CLI manifest")
    core_bytes, _ = read_bounded(core_manifest_path, MAX_CONFIG_BYTES, "core manifest")
    cli = parse_json_bytes(cli_bytes, "CLI manifest")
    core = parse_json_bytes(core_bytes, "core manifest")
    cli_valid = (
        isinstance(cli, dict)
        and cli.get("name") == "@contextlint/cli"
        and cli.get("version") == VERSION
        and cli.get("type") == "module"
        and cli.get("bin") == {"contextlint": "dist/index.js"}
        and isinstance(cli.get("dependencies"), dict)
        and cli["dependencies"].get("@contextlint/core") == VERSION
    )
    core_valid = (
        isinstance(core, dict)
        and core.get("name") == "@contextlint/core"
        and core.get("version") == VERSION
        and core.get("type") == "module"
    )
    if not cli_valid or not core_valid:
        reject(f"contextlint package graph is not the exact supported {VERSION} pair")
    return graph, cli_entry


def validate_config(config_bytes):
    config = parse_json_bytes(config_bytes, "contextlint.config.json")
    if not isinstance(config, dict):
        reject("contextlint.config.json must contain a JSON object")
    rules = config.get("rules")
    if not isinstance(rules, list) or not rules:
        reject("contextlint.config.json must declare at least one rule")
    for index, entry in enumerate(rules):
        if not isinstance(entry, dict) or entry.get("rule") not in RULES:
            reject(f"contextlint.config.json rules[{index}] is not a pinned built-in rule")
    return config


def inventory_workspace(workspace):
    files = []
    seen_inodes = set()
    entries = 0
    total_bytes = 0

    def visit(directory):
        nonlocal entries, total_bytes
        try:
            directory_metadata = os.lstat(directory)
            if not stat.S_ISDIR(directory_metadata.st_mode) or stat.S_ISLNK(directory_metadata.st_mode):
                reject(f"workspace traversal encountered a non-directory: {directory}")
            children = sorted(os.scandir(directory), key=lambda item: item.name)
        except AdapterFailure:
            raise
        except OSError as error:
            reject(f"cannot inventory workspace directory {directory}: {error}")
        for child in children:
            entries += 1
            if entries > MAX_ENTRIES:
                reject(f"workspace inventory exceeds {MAX_ENTRIES} entries")
            path = child.path
            try:
                metadata = child.stat(follow_symlinks=False)
            except OSError as error:
                reject(f"cannot inspect workspace entry {path}: {error}")
            if stat.S_ISLNK(metadata.st_mode):
                reject(f"workspace inventory rejects symbolic links: {path}")
            if stat.S_ISDIR(metadata.st_mode):
                if child.name in EXCLUDED_DIRECTORIES:
                    continue
                reject_glob_magic_path(path, "workspace inventory path")
                visit(path)
                continue
            lowered = child.name.lower()
            if not (lowered.endswith(".md") or lowered.endswith(".markdown")):
                continue
            reject_glob_magic_path(path, "workspace inventory path")
            if not stat.S_ISREG(metadata.st_mode):
                reject(f"Markdown inventory entry is not a regular file: {path}")
            if metadata.st_nlink != 1:
                reject(f"Markdown inventory entry must have one hard link: {path}")
            inode = (metadata.st_dev, metadata.st_ino)
            if inode in seen_inodes:
                reject(f"Markdown inventory contains a duplicate inode: {path}")
            seen_inodes.add(inode)
            if len(files) >= MAX_FILES:
                reject(f"workspace inventory exceeds {MAX_FILES} Markdown files")
            data, identity = read_bounded(path, MAX_FILE_BYTES, "Markdown file")
            total_bytes += len(data)
            if total_bytes > MAX_TOTAL_BYTES:
                reject(f"workspace Markdown inventory exceeds {MAX_TOTAL_BYTES} bytes")
            files.append((os.path.realpath(path), identity))

    visit(workspace)
    files.sort(key=lambda item: item[0])
    if not files:
        reject("workspace contains no physical Markdown files")
    return files


PRIVATE_ROOT_PREFIX = "velvet-glove-contextlint-probe-"


def normalize_private_error(error, root=None):
    message = str(error)
    if root is not None:
        return message.replace(root, "<private-probe>")
    if isinstance(error, OSError) and error.filename is not None:
        candidate = os.path.abspath(os.fsdecode(error.filename))
        parent = os.path.dirname(candidate)
        if os.path.basename(candidate).startswith(PRIVATE_ROOT_PREFIX):
            return message.replace(candidate, "<private-probe>")
        if os.path.basename(parent).startswith(PRIVATE_ROOT_PREFIX):
            return message.replace(parent, "<private-probe>")
    return message


def create_private_run_root(workspace):
    base = os.environ.get("TMPDIR", "/tmp")
    if not os.path.isabs(base):
        reject("TMPDIR must be absolute")
    reject_glob_magic_path(base, "TMPDIR")
    base = os.path.realpath(base)
    reject_glob_magic_path(base, "resolved TMPDIR")
    if not os.path.isdir(base):
        reject(f"TMPDIR is not a directory: {base}")
    try:
        inside_workspace = os.path.commonpath((workspace, base)) == workspace
    except ValueError:
        inside_workspace = False
    if inside_workspace:
        reject("TMPDIR must resolve outside the Contextlint workspace")
    root = None
    created = []
    try:
        root = tempfile.mkdtemp(prefix=PRIVATE_ROOT_PREFIX, dir=base)
        created.append(root)
        os.chmod(root, 0o700)
        for name in ("home", "tmp", "xdg-cache"):
            path = os.path.join(root, name)
            os.mkdir(path, 0o700)
            os.chmod(path, 0o700)
            created.append(path)
    except OSError as error:
        for path in reversed(created):
            try:
                os.rmdir(path)
            except OSError:
                pass
        reject(
            "cannot create private completion-probe root: "
            + normalize_private_error(error, root)
        )
    return root


def write_private_file(path, data):
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags, 0o600)
    try:
        os.fchmod(descriptor, 0o600)
        offset = 0
        while offset < len(data):
            offset += os.write(descriptor, data[offset:])
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


process = None
pending_signal = None
reported_signal = None
cleaning = False
active_workspace = None
private_run_root = None
handled_signals = (signal.SIGHUP, signal.SIGINT, signal.SIGTERM)


def signal_group(signum):
    if process is None:
        return
    try:
        os.killpg(process.pid, signum)
    except (OSError, ValueError):
        pass


def process_group_exists():
    if process is None:
        return False
    try:
        os.killpg(process.pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def sweep_process_group():
    if not process_group_exists():
        return False
    signal_group(signal.SIGKILL)
    deadline = time.monotonic() + 1
    while process_group_exists() and time.monotonic() < deadline:
        time.sleep(0.01)
    if process_group_exists():
        raise AdapterFailure("cannot reap same-group descendants after child exit")
    return True


def stop_child(initial_signal=None):
    global process, cleaning
    child = process
    if child is None:
        return None
    cleanup_error = None
    cleaning = True
    try:
        try:
            running = child.poll() is None
        except (OSError, ValueError):
            running = True
        if running:
            signal_group(initial_signal if initial_signal is not None else signal.SIGTERM)
            try:
                child.wait(timeout=1)
            except (OSError, ValueError, subprocess.TimeoutExpired):
                pass
        signal_group(signal.SIGKILL)
        try:
            child.wait(timeout=1)
        except (OSError, ValueError, subprocess.TimeoutExpired):
            pass
        deadline = time.monotonic() + 1
        while process_group_exists() and time.monotonic() < deadline:
            time.sleep(0.01)
        if process_group_exists():
            cleanup_error = AdapterFailure(
                "cannot reap same-group descendants during child cleanup"
            )
    finally:
        process = None
        cleaning = False
    return cleanup_error


def forward_signal(signum, _frame):
    global pending_signal
    pending_signal = signum
    if process is not None and not cleaning:
        signal_group(signum)
        raise AdapterSignal(signum)


def append_adapter_error(primary, secondary):
    if secondary is None:
        return primary
    if primary is None:
        return secondary
    return AdapterFailure(f"{primary}; {secondary}")


def apply_pending_signal(primary):
    global reported_signal
    if pending_signal is None or pending_signal == reported_signal:
        return primary
    reported_signal = pending_signal
    return append_adapter_error(primary, AdapterSignal(pending_signal))


def drain_blocked_signals(primary):
    global pending_signal
    drained = False
    while True:
        queued = sorted(set(signal.sigpending()).intersection(handled_signals), key=int)
        if not queued:
            return primary, drained
        pending_signal = int(signal.sigwait({queued[0]}))
        primary = apply_pending_signal(primary)
        drained = True


def child_environment(run_root):
    environment = {
        "PATH": "/usr/bin:/bin",
        "HOME": os.path.join(run_root, "home"),
        "TMPDIR": os.path.join(run_root, "tmp"),
        "XDG_CACHE_HOME": os.path.join(run_root, "xdg-cache"),
        "LANG": "C",
        "LC_ALL": "C",
        "TZ": "UTC",
        "TERM": "dumb",
        "CI": "1",
        "NO_COLOR": "1",
        "CLICOLOR": "0",
        "FORCE_COLOR": "0",
        "NODE_DISABLE_COLORS": "1",
        "UV_THREADPOOL_SIZE": "1",
    }
    for name in (
        "VELVET_GLOVE_TOOL_TRACE_DIR",
        "VELVET_GLOVE_TOOL_TRACE_SENTINEL",
    ):
        if name in os.environ:
            environment[name] = os.environ[name]
    return environment


def run_child(arguments, cwd, environment):
    global process, pending_signal
    stdout_chunks = []
    stderr_chunks = []
    total = 0
    child = None
    selector = selectors.DefaultSelector()
    spawn_mask = None
    leader_exit_deadline = None
    try:
        spawn_mask = signal.pthread_sigmask(signal.SIG_BLOCK, handled_signals)
        try:
            queued = sorted(
                set(signal.sigpending()).intersection(handled_signals), key=int
            )
            if queued:
                pending_signal = int(signal.sigwait({queued[0]}))
            if pending_signal is not None:
                raise AdapterSignal(pending_signal)
            child = subprocess.Popen(
                arguments,
                cwd=cwd,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=environment,
                start_new_session=True,
            )
            process = child
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, spawn_mask)
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        for stream, target in ((process.stdout, stdout_chunks), (process.stderr, stderr_chunks)):
            if stream is None:
                reject("failed to capture contextlint output")
            os.set_blocking(stream.fileno(), False)
            selector.register(stream, selectors.EVENT_READ, target)
        while selector.get_map():
            if pending_signal is not None:
                raise AdapterSignal(pending_signal)
            events = selector.select(timeout=0.1)
            for key, _ in events:
                chunk = os.read(key.fileobj.fileno(), 65536)
                if chunk:
                    total += len(chunk)
                    if total > MAX_OUTPUT_BYTES:
                        raise BufferError(
                            f"combined contextlint output exceeded {MAX_OUTPUT_BYTES} bytes"
                        )
                    key.data.append(chunk)
                else:
                    selector.unregister(key.fileobj)
                    key.fileobj.close()
            if process.poll() is not None and selector.get_map():
                if sweep_process_group():
                    raise AdapterFailure(
                        "native Contextlint left same-group descendants after child exit"
                    )
                if leader_exit_deadline is None:
                    leader_exit_deadline = time.monotonic() + 0.25
                elif time.monotonic() >= leader_exit_deadline:
                    raise AdapterFailure(
                        "native Contextlint child exited without closing output pipes"
                    )
        returncode = process.wait()
        if sweep_process_group():
            raise AdapterFailure(
                "native Contextlint left same-group descendants after child exit"
            )
        process = None
        return returncode, b"".join(stdout_chunks), b"".join(stderr_chunks)
    except AdapterSignal as error:
        cleanup_error = stop_child(pending_signal)
        if cleanup_error is not None:
            raise append_adapter_error(error, cleanup_error) from error
        raise
    except BaseException as error:
        cleanup_error = stop_child()
        if cleanup_error is not None:
            raise append_adapter_error(error, cleanup_error) from error
        raise
    finally:
        selector.close()
        if child is not None:
            for stream in (child.stdout, child.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass


def node_arguments(node_program, cli_entry, readable_roots, config, cwd, files):
    arguments = [node_program, "--disable-proto=throw", "--permission"]
    for root in readable_roots:
        arguments.append(f"--allow-fs-read={root}")
    arguments.extend((
        cli_entry,
        "lint",
        "--config", config,
        "--cwd", cwd,
        "--format", "json",
        "--",
    ))
    arguments.extend(files)
    return arguments


def parse_report(stdout_bytes, description):
    report = parse_json_bytes(stdout_bytes, description)
    if not isinstance(report, list):
        reject(f"{description} is not a JSON array")
    expected_keys = {"file", "line", "severity", "message", "ruleId"}
    for index, item in enumerate(report):
        valid = (
            isinstance(item, dict)
            and set(item) == expected_keys
            and isinstance(item.get("file"), str)
            and type(item.get("line")) is int
            and item["line"] >= 0
            and item.get("severity") in ("error", "warning")
            and isinstance(item.get("message"), str)
            and isinstance(item.get("ruleId"), str)
            and re.fullmatch(r"[A-Z]{3}-[0-9]{3}", item["ruleId"]) is not None
        )
        if not valid:
            reject(f"{description} entry {index} has an invalid shape")
    return report


def verify_snapshots(paths):
    for path, expected, limit, description in paths:
        _, observed = read_bounded(path, limit, description)
        if observed != expected:
            reject(f"{description} changed during contextlint: {path}")


def sanitize(text, workspace, run_root):
    stable = text.replace(run_root, "<private-probe>")
    stable = stable.replace(workspace, "<workspace>")
    return stable


def cleanup_private_root(root):
    if root is None:
        return
    for name in ("contextlint.config.json", "project.config.json", "probe.md"):
        path = os.path.join(root, name)
        if os.path.lexists(path):
            os.unlink(path)
    for name in ("home", "tmp", "xdg-cache"):
        path = os.path.join(root, name)
        if os.path.lexists(path):
            os.rmdir(path)
    os.rmdir(root)


def main():
    global active_workspace, private_run_root, cleaning, reported_signal
    if len(sys.argv) < 6:
        reject("invalid adapter arguments")
    node_name = sys.argv[1]
    tool_name = sys.argv[2]
    indicator_argument = sys.argv[3]
    payload = sys.argv[4:]
    if payload.count(MARKER) != 1 or payload[0] != MARKER:
        reject("forwarded arguments are unsupported and file marker is invalid")
    candidates = payload[1:]
    if not candidates:
        reject("runner selected zero candidate files")

    node_program = resolve_program(node_name, "Node executable")
    tool_program = resolve_program(tool_name, "contextlint executable")
    graph, cli_entry = validate_package_graph(tool_program)

    lexical_indicator = os.path.abspath(indicator_argument)
    if os.path.basename(lexical_indicator) != "contextlint.config.json":
        reject(f"invalid workspace indicator: {indicator_argument}")
    indicator = os.path.realpath(lexical_indicator)
    if lexical_indicator != indicator:
        reject("workspace indicator traverses a symbolic link")
    workspace = os.path.dirname(indicator)
    active_workspace = workspace
    reject_glob_magic_path(indicator, "workspace indicator")
    config_bytes, config_identity = read_bounded(
        indicator, MAX_CONFIG_BYTES, "contextlint.config.json"
    )
    validate_config(config_bytes)

    inventory = inventory_workspace(workspace)
    inventory_paths = [path for path, _ in inventory]
    inventory_set = set(inventory_paths)
    candidate_paths = []
    for candidate in candidates:
        absolute = os.path.abspath(candidate)
        reject_glob_magic_path(absolute, "runner candidate")
        canonical = os.path.realpath(absolute)
        if absolute != canonical or canonical not in inventory_set:
            reject(f"runner candidate is outside the physical Markdown inventory: {candidate}")
        candidate_paths.append(canonical)
    if len(set(candidate_paths)) != len(candidate_paths):
        reject("runner candidate list contains duplicates")

    snapshots = [(indicator, config_identity, MAX_CONFIG_BYTES, "contextlint.config.json")]
    snapshots.extend(
        (path, identity, MAX_FILE_BYTES, "Markdown file")
        for path, identity in inventory
    )

    run_root = None
    result = None
    try:
        run_root = create_private_run_root(workspace)
        private_run_root = run_root
        probe_config = os.path.join(run_root, "contextlint.config.json")
        project_config = os.path.join(run_root, "project.config.json")
        probe_document = os.path.join(run_root, "probe.md")
        write_private_file(probe_config, PROBE_CONFIG)
        write_private_file(project_config, config_bytes)
        write_private_file(probe_document, PROBE_DOCUMENT)
        private_config_bytes, _ = read_bounded(
            project_config, MAX_CONFIG_BYTES, "private contextlint.config.json copy"
        )
        if private_config_bytes != config_bytes:
            reject("private contextlint.config.json copy changed while being created")
        environment = child_environment(run_root)

        probe_args = node_arguments(
            node_program,
            cli_entry,
            (graph, run_root),
            probe_config,
            run_root,
            (probe_document,),
        )
        probe_status, probe_stdout, probe_stderr = run_child(
            probe_args, run_root, environment
        )
        probe_report = parse_report(probe_stdout, "private completion report")
        if probe_status != 1 or probe_stderr or probe_report != PROBE_REPORT:
            reject(
                "private SEC-001 completion probe did not return its exact pinned result"
            )

        command_args = node_arguments(
            node_program,
            cli_entry,
            (graph, workspace, run_root),
            project_config,
            workspace,
            inventory_paths,
        )
        status, stdout_bytes, stderr_bytes = run_child(
            command_args, workspace, environment
        )
        verify_snapshots(snapshots)

        if status in (0, 1):
            if stderr_bytes:
                reject("contextlint emitted stderr with a lint status")
            report = parse_report(stdout_bytes, "project completion report")
            has_errors = any(item["severity"] == "error" for item in report)
            if (status == 1) != has_errors:
                reject("contextlint exit status contradicts its JSON severities")
            relative_inventory = {
                os.path.relpath(path, workspace).replace(os.sep, "/")
                for path in inventory_paths
            }
            for item in report:
                if item["file"] != "(project)" and item["file"] not in relative_inventory:
                    reject(
                        f"contextlint attributed a diagnostic outside the inventory: {item['file']}"
                    )
                item["message"] = sanitize(item["message"], workspace, run_root)
            report.sort(
                key=lambda item: (
                    item["file"], item["line"], item["ruleId"],
                    item["severity"], item["message"],
                )
            )
            stable = json.dumps(
                report, ensure_ascii=False, sort_keys=True, separators=(",", ":")
            ) + "\n"
            result = (1 if report else 0, stable.encode("utf-8"), b"")
        else:
            stdout = sanitize(stdout_bytes.decode("utf-8", "replace"), workspace, run_root)
            stderr = sanitize(stderr_bytes.decode("utf-8", "replace"), workspace, run_root)
            diagnostic = stdout.encode("utf-8") + stderr.encode("utf-8")
            diagnostic += (
                f"velvet-glove-contextlint: contextlint exited with operational status {status}\n"
            ).encode("utf-8")
            result = (2, b"", diagnostic)
    finally:
        primary_error = sys.exc_info()[1]
        cleanup_error = stop_child()
        cleaning = True
        try:
            if run_root is not None:
                cleanup_private_root(run_root)
        except OSError as error:
            cleanup_failure = AdapterFailure(
                "cannot remove private completion-probe root: "
                + normalize_private_error(error, run_root)
            )
            cleanup_error = append_adapter_error(cleanup_error, cleanup_failure)
        finally:
            cleaning = False
        if cleanup_error is not None:
            if isinstance(primary_error, AdapterSignal):
                reported_signal = primary_error.signum
            if primary_error is not None:
                raise append_adapter_error(primary_error, cleanup_error)
            raise cleanup_error
    if pending_signal is not None:
        raise AdapterSignal(pending_signal)
    if result is None:
        reject("contextlint adapter produced no result")
    return result


previous_handlers = {}
adapter_error = None
result = None
try:
    for signum in handled_signals:
        previous_handlers[signum] = signal.signal(signum, forward_signal)
    result = main()
except AdapterSignal as error:
    adapter_error = append_adapter_error(error, stop_child(error.signum))
    reported_signal = error.signum
except AdapterFailure as error:
    adapter_error = append_adapter_error(error, stop_child())
except BaseException as error:
    adapter_error = append_adapter_error(
        RuntimeError(f"adapter failure: {error}"), stop_child()
    )
finally:
    cleaning = True
    blocked_mask = None
    try:
        try:
            blocked_mask = signal.pthread_sigmask(signal.SIG_BLOCK, handled_signals)
        except (OSError, ValueError) as error:
            adapter_error = append_adapter_error(
                adapter_error, AdapterFailure(f"cannot block cleanup signals: {error}")
            )
        adapter_error = apply_pending_signal(adapter_error)
        if blocked_mask is not None:
            while True:
                adapter_error, drained = drain_blocked_signals(adapter_error)
                if not drained:
                    break
    finally:
        # Keep these signals blocked through diagnostics and process exit.
        # Unblocking after restoring default handlers would reopen the
        # post-cleanup termination window closed by this cutoff.
        try:
            for signum, handler in previous_handlers.items():
                try:
                    signal.signal(signum, handler)
                except (OSError, ValueError):
                    pass
        finally:
            cleaning = False

if adapter_error is not None:
    message = normalize_private_error(adapter_error, private_run_root)
    if active_workspace is not None:
        message = message.replace(active_workspace, "<workspace>")
    print(f"velvet-glove-contextlint: {message}", file=sys.stderr)
    raise SystemExit(2)
if result is None:
    print("velvet-glove-contextlint: adapter produced no result", file=sys.stderr)
    raise SystemExit(2)
status, stdout_bytes, stderr_bytes = result
if stdout_bytes:
    sys.stdout.buffer.write(stdout_bytes)
if stderr_bytes:
    sys.stderr.buffer.write(stderr_bytes)
raise SystemExit(status)

import hashlib
import json
import os
import re
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time

MARKER = "__VELVET_GLOVE_CONTEXTLINT_FILES__"
VERSION = "1.1.1"
MAX_CONFIG_BYTES = 1024 * 1024
MAX_FILE_BYTES = 16 * 1024 * 1024
MAX_TOTAL_BYTES = 64 * 1024 * 1024
MAX_FILES = 4096
MAX_ENTRIES = 100000
MAX_OUTPUT_BYTES = 16 * 1024 * 1024
EXCLUDED_DIRECTORIES = frozenset((".git", "node_modules", ".velvet-glove"))
# glob 13.0.6 expands braces before minimatch 10.2.6 parses a pattern.
# This is minimatch.escape(..., magicalBraces=True)'s POSIX magic set.
GLOB_MAGIC = frozenset("*?()[]{}\\")
RULES = frozenset((
    "tbl001", "tbl002", "tbl003", "tbl004", "tbl005", "tbl006",
    "sec001", "sec002", "str001",
    "ref001", "ref002", "ref003", "ref004", "ref005", "ref006",
    "chk001", "ctx001", "ctx002", "grp001", "grp002", "grp003",
))
PROBE_CONFIG = (
    b'{"rules":[{"rule":"sec001","options":{"sections":'
    b'["__VELVET_GLOVE_CONTEXTLINT_COMPLETION__"]}}]}\n'
)
PROBE_DOCUMENT = b"# Probe\n"
PROBE_REPORT = [{
    "file": "probe.md",
    "line": 0,
    "severity": "error",
    "message": 'Missing required section "__VELVET_GLOVE_CONTEXTLINT_COMPLETION__"',
    "ruleId": "SEC-001",
}]


class AdapterFailure(Exception):
    pass


class AdapterSignal(BaseException):
    def __init__(self, signum):
        super().__init__(f"received signal {signum}")
        self.signum = signum


def reject(message):
    raise AdapterFailure(message)


def reject_glob_magic_path(path, description):
    absolute = os.path.abspath(path)
    for component in absolute.split(os.sep):
        magic = "".join(sorted(set(component).intersection(GLOB_MAGIC)))
        if magic:
            reject(
                f"{description} contains Contextlint glob magic {magic!r}: {path}"
            )


def duplicate_safe_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            reject(f"configuration contains duplicate key {key!r}")
        value[key] = item
    return value


def read_bounded(path, limit, description):
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        before = os.lstat(path)
        if not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(before.st_mode):
            reject(f"{description} is not a regular file: {path}")
        if before.st_nlink != 1:
            reject(f"{description} must have exactly one hard link: {path}")
        descriptor = os.open(path, flags)
        try:
            opened = os.fstat(descriptor)
            if (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino):
                reject(f"{description} changed while opening: {path}")
            chunks = []
            total = 0
            while True:
                chunk = os.read(descriptor, min(65536, limit + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > limit:
                    reject(f"{description} exceeds {limit} bytes: {path}")
        finally:
            os.close(descriptor)
    except AdapterFailure:
        raise
    except OSError as error:
        reject(f"cannot read {description} {path}: {error}")
    data = b"".join(chunks)
    identity = (
        before.st_dev,
        before.st_ino,
        before.st_mode,
        before.st_nlink,
        before.st_size,
        before.st_mtime_ns,
        hashlib.sha256(data).hexdigest(),
    )
    return data, identity


def parse_json_bytes(data, description):
    try:
        text = data.decode("utf-8")
        return json.loads(text, object_pairs_hook=duplicate_safe_object)
    except AdapterFailure:
        raise
    except (UnicodeError, json.JSONDecodeError) as error:
        reject(f"invalid UTF-8 JSON in {description}: {error}")


def resolve_program(name, description):
    if not name or "\x00" in name:
        reject(f"invalid {description} name")
    candidate = shutil.which(name)
    if candidate is None:
        reject(f"cannot resolve {description} {name!r}")
    absolute = os.path.abspath(candidate)
    try:
        metadata = os.stat(absolute)
    except OSError as error:
        reject(f"cannot inspect {description} {absolute}: {error}")
    if not stat.S_ISREG(metadata.st_mode) or not os.access(absolute, os.X_OK):
        reject(f"{description} is not an executable regular file: {absolute}")
    return absolute


def validate_package_graph(tool_program):
    resolved = os.path.realpath(tool_program)
    cursor = os.path.dirname(resolved)
    graph = None
    while True:
        if os.path.basename(cursor) == "node_modules":
            graph = cursor
            break
        parent = os.path.dirname(cursor)
        if parent == cursor:
            break
        cursor = parent
    if graph is None:
        reject(f"contextlint executable is outside a node_modules graph: {tool_program}")
    graph = os.path.realpath(graph)
    cli_entry = os.path.realpath(
        os.path.join(graph, "@contextlint", "cli", "dist", "index.js")
    )
    if resolved != cli_entry:
        reject(
            "contextlint executable does not resolve to "
            f"@contextlint/cli/dist/index.js: {tool_program}"
        )
    cli_manifest_path = os.path.join(graph, "@contextlint", "cli", "package.json")
    core_manifest_path = os.path.join(graph, "@contextlint", "core", "package.json")
    cli_bytes, _ = read_bounded(cli_manifest_path, MAX_CONFIG_BYTES, "CLI manifest")
    core_bytes, _ = read_bounded(core_manifest_path, MAX_CONFIG_BYTES, "core manifest")
    cli = parse_json_bytes(cli_bytes, "CLI manifest")
    core = parse_json_bytes(core_bytes, "core manifest")
    cli_valid = (
        isinstance(cli, dict)
        and cli.get("name") == "@contextlint/cli"
        and cli.get("version") == VERSION
        and cli.get("type") == "module"
        and cli.get("bin") == {"contextlint": "dist/index.js"}
        and isinstance(cli.get("dependencies"), dict)
        and cli["dependencies"].get("@contextlint/core") == VERSION
    )
    core_valid = (
        isinstance(core, dict)
        and core.get("name") == "@contextlint/core"
        and core.get("version") == VERSION
        and core.get("type") == "module"
    )
    if not cli_valid or not core_valid:
        reject(f"contextlint package graph is not the exact supported {VERSION} pair")
    return graph, cli_entry


def validate_config(config_bytes):
    config = parse_json_bytes(config_bytes, "contextlint.config.json")
    if not isinstance(config, dict):
        reject("contextlint.config.json must contain a JSON object")
    rules = config.get("rules")
    if not isinstance(rules, list) or not rules:
        reject("contextlint.config.json must declare at least one rule")
    for index, entry in enumerate(rules):
        if not isinstance(entry, dict) or entry.get("rule") not in RULES:
            reject(f"contextlint.config.json rules[{index}] is not a pinned built-in rule")
    return config


def inventory_workspace(workspace):
    files = []
    seen_inodes = set()
    entries = 0
    total_bytes = 0

    def visit(directory):
        nonlocal entries, total_bytes
        try:
            directory_metadata = os.lstat(directory)
            if not stat.S_ISDIR(directory_metadata.st_mode) or stat.S_ISLNK(directory_metadata.st_mode):
                reject(f"workspace traversal encountered a non-directory: {directory}")
            children = sorted(os.scandir(directory), key=lambda item: item.name)
        except AdapterFailure:
            raise
        except OSError as error:
            reject(f"cannot inventory workspace directory {directory}: {error}")
        for child in children:
            entries += 1
            if entries > MAX_ENTRIES:
                reject(f"workspace inventory exceeds {MAX_ENTRIES} entries")
            path = child.path
            try:
                metadata = child.stat(follow_symlinks=False)
            except OSError as error:
                reject(f"cannot inspect workspace entry {path}: {error}")
            if stat.S_ISLNK(metadata.st_mode):
                reject(f"workspace inventory rejects symbolic links: {path}")
            if stat.S_ISDIR(metadata.st_mode):
                if child.name in EXCLUDED_DIRECTORIES:
                    continue
                reject_glob_magic_path(path, "workspace inventory path")
                visit(path)
                continue
            lowered = child.name.lower()
            if not (lowered.endswith(".md") or lowered.endswith(".markdown")):
                continue
            reject_glob_magic_path(path, "workspace inventory path")
            if not stat.S_ISREG(metadata.st_mode):
                reject(f"Markdown inventory entry is not a regular file: {path}")
            if metadata.st_nlink != 1:
                reject(f"Markdown inventory entry must have one hard link: {path}")
            inode = (metadata.st_dev, metadata.st_ino)
            if inode in seen_inodes:
                reject(f"Markdown inventory contains a duplicate inode: {path}")
            seen_inodes.add(inode)
            if len(files) >= MAX_FILES:
                reject(f"workspace inventory exceeds {MAX_FILES} Markdown files")
            data, identity = read_bounded(path, MAX_FILE_BYTES, "Markdown file")
            total_bytes += len(data)
            if total_bytes > MAX_TOTAL_BYTES:
                reject(f"workspace Markdown inventory exceeds {MAX_TOTAL_BYTES} bytes")
            files.append((os.path.realpath(path), identity))

    visit(workspace)
    files.sort(key=lambda item: item[0])
    if not files:
        reject("workspace contains no physical Markdown files")
    return files


PRIVATE_ROOT_PREFIX = "velvet-glove-contextlint-probe-"


def normalize_private_error(error, root=None):
    message = str(error)
    if root is not None:
        return message.replace(root, "<private-probe>")
    if isinstance(error, OSError) and error.filename is not None:
        candidate = os.path.abspath(os.fsdecode(error.filename))
        parent = os.path.dirname(candidate)
        if os.path.basename(candidate).startswith(PRIVATE_ROOT_PREFIX):
            return message.replace(candidate, "<private-probe>")
        if os.path.basename(parent).startswith(PRIVATE_ROOT_PREFIX):
            return message.replace(parent, "<private-probe>")
    return message


def create_private_run_root(workspace):
    base = os.environ.get("TMPDIR", "/tmp")
    if not os.path.isabs(base):
        reject("TMPDIR must be absolute")
    reject_glob_magic_path(base, "TMPDIR")
    base = os.path.realpath(base)
    reject_glob_magic_path(base, "resolved TMPDIR")
    if not os.path.isdir(base):
        reject(f"TMPDIR is not a directory: {base}")
    try:
        inside_workspace = os.path.commonpath((workspace, base)) == workspace
    except ValueError:
        inside_workspace = False
    if inside_workspace:
        reject("TMPDIR must resolve outside the Contextlint workspace")
    root = None
    created = []
    try:
        root = tempfile.mkdtemp(prefix=PRIVATE_ROOT_PREFIX, dir=base)
        created.append(root)
        os.chmod(root, 0o700)
        for name in ("home", "tmp", "xdg-cache"):
            path = os.path.join(root, name)
            os.mkdir(path, 0o700)
            os.chmod(path, 0o700)
            created.append(path)
    except OSError as error:
        for path in reversed(created):
            try:
                os.rmdir(path)
            except OSError:
                pass
        reject(
            "cannot create private completion-probe root: "
            + normalize_private_error(error, root)
        )
    return root


def write_private_file(path, data):
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags, 0o600)
    try:
        os.fchmod(descriptor, 0o600)
        offset = 0
        while offset < len(data):
            offset += os.write(descriptor, data[offset:])
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


process = None
pending_signal = None
reported_signal = None
cleaning = False
active_workspace = None
private_run_root = None
handled_signals = (signal.SIGHUP, signal.SIGINT, signal.SIGTERM)


def signal_group(signum):
    if process is None:
        return
    try:
        os.killpg(process.pid, signum)
    except (OSError, ValueError):
        pass


def process_group_exists():
    if process is None:
        return False
    try:
        os.killpg(process.pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def sweep_process_group():
    if not process_group_exists():
        return False
    signal_group(signal.SIGKILL)
    deadline = time.monotonic() + 1
    while process_group_exists() and time.monotonic() < deadline:
        time.sleep(0.01)
    if process_group_exists():
        raise AdapterFailure("cannot reap same-group descendants after child exit")
    return True


def stop_child(initial_signal=None):
    global process, cleaning
    child = process
    if child is None:
        return None
    cleanup_error = None
    cleaning = True
    try:
        try:
            running = child.poll() is None
        except (OSError, ValueError):
            running = True
        if running:
            signal_group(initial_signal if initial_signal is not None else signal.SIGTERM)
            try:
                child.wait(timeout=1)
            except (OSError, ValueError, subprocess.TimeoutExpired):
                pass
        signal_group(signal.SIGKILL)
        try:
            child.wait(timeout=1)
        except (OSError, ValueError, subprocess.TimeoutExpired):
            pass
        deadline = time.monotonic() + 1
        while process_group_exists() and time.monotonic() < deadline:
            time.sleep(0.01)
        if process_group_exists():
            cleanup_error = AdapterFailure(
                "cannot reap same-group descendants during child cleanup"
            )
    finally:
        process = None
        cleaning = False
    return cleanup_error


def forward_signal(signum, _frame):
    global pending_signal
    pending_signal = signum
    if process is not None and not cleaning:
        signal_group(signum)
        raise AdapterSignal(signum)


def append_adapter_error(primary, secondary):
    if secondary is None:
        return primary
    if primary is None:
        return secondary
    return AdapterFailure(f"{primary}; {secondary}")


def apply_pending_signal(primary):
    global reported_signal
    if pending_signal is None or pending_signal == reported_signal:
        return primary
    reported_signal = pending_signal
    return append_adapter_error(primary, AdapterSignal(pending_signal))


def drain_blocked_signals(primary):
    global pending_signal
    drained = False
    while True:
        queued = sorted(set(signal.sigpending()).intersection(handled_signals), key=int)
        if not queued:
            return primary, drained
        pending_signal = int(signal.sigwait({queued[0]}))
        primary = apply_pending_signal(primary)
        drained = True


def child_environment(run_root):
    environment = {
        "PATH": "/usr/bin:/bin",
        "HOME": os.path.join(run_root, "home"),
        "TMPDIR": os.path.join(run_root, "tmp"),
        "XDG_CACHE_HOME": os.path.join(run_root, "xdg-cache"),
        "LANG": "C",
        "LC_ALL": "C",
        "TZ": "UTC",
        "TERM": "dumb",
        "CI": "1",
        "NO_COLOR": "1",
        "CLICOLOR": "0",
        "FORCE_COLOR": "0",
        "NODE_DISABLE_COLORS": "1",
        "UV_THREADPOOL_SIZE": "1",
    }
    for name in (
        "VELVET_GLOVE_TOOL_TRACE_DIR",
        "VELVET_GLOVE_TOOL_TRACE_SENTINEL",
    ):
        if name in os.environ:
            environment[name] = os.environ[name]
    return environment


def run_child(arguments, cwd, environment):
    global process, pending_signal
    stdout_chunks = []
    stderr_chunks = []
    total = 0
    child = None
    selector = selectors.DefaultSelector()
    spawn_mask = None
    leader_exit_deadline = None
    try:
        spawn_mask = signal.pthread_sigmask(signal.SIG_BLOCK, handled_signals)
        try:
            queued = sorted(
                set(signal.sigpending()).intersection(handled_signals), key=int
            )
            if queued:
                pending_signal = int(signal.sigwait({queued[0]}))
            if pending_signal is not None:
                raise AdapterSignal(pending_signal)
            child = subprocess.Popen(
                arguments,
                cwd=cwd,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=environment,
                start_new_session=True,
            )
            process = child
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, spawn_mask)
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        for stream, target in ((process.stdout, stdout_chunks), (process.stderr, stderr_chunks)):
            if stream is None:
                reject("failed to capture contextlint output")
            os.set_blocking(stream.fileno(), False)
            selector.register(stream, selectors.EVENT_READ, target)
        while selector.get_map():
            if pending_signal is not None:
                raise AdapterSignal(pending_signal)
            events = selector.select(timeout=0.1)
            for key, _ in events:
                chunk = os.read(key.fileobj.fileno(), 65536)
                if chunk:
                    total += len(chunk)
                    if total > MAX_OUTPUT_BYTES:
                        raise BufferError(
                            f"combined contextlint output exceeded {MAX_OUTPUT_BYTES} bytes"
                        )
                    key.data.append(chunk)
                else:
                    selector.unregister(key.fileobj)
                    key.fileobj.close()
            if process.poll() is not None and selector.get_map():
                if sweep_process_group():
                    raise AdapterFailure(
                        "native Contextlint left same-group descendants after child exit"
                    )
                if leader_exit_deadline is None:
                    leader_exit_deadline = time.monotonic() + 0.25
                elif time.monotonic() >= leader_exit_deadline:
                    raise AdapterFailure(
                        "native Contextlint child exited without closing output pipes"
                    )
        returncode = process.wait()
        if sweep_process_group():
            raise AdapterFailure(
                "native Contextlint left same-group descendants after child exit"
            )
        process = None
        return returncode, b"".join(stdout_chunks), b"".join(stderr_chunks)
    except AdapterSignal as error:
        cleanup_error = stop_child(pending_signal)
        if cleanup_error is not None:
            raise append_adapter_error(error, cleanup_error) from error
        raise
    except BaseException as error:
        cleanup_error = stop_child()
        if cleanup_error is not None:
            raise append_adapter_error(error, cleanup_error) from error
        raise
    finally:
        selector.close()
        if child is not None:
            for stream in (child.stdout, child.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass


def node_arguments(node_program, cli_entry, readable_roots, config, cwd, files):
    arguments = [node_program, "--disable-proto=throw", "--permission"]
    for root in readable_roots:
        arguments.append(f"--allow-fs-read={root}")
    arguments.extend((
        cli_entry,
        "lint",
        "--config", config,
        "--cwd", cwd,
        "--format", "json",
        "--",
    ))
    arguments.extend(files)
    return arguments


def parse_report(stdout_bytes, description):
    report = parse_json_bytes(stdout_bytes, description)
    if not isinstance(report, list):
        reject(f"{description} is not a JSON array")
    expected_keys = {"file", "line", "severity", "message", "ruleId"}
    for index, item in enumerate(report):
        valid = (
            isinstance(item, dict)
            and set(item) == expected_keys
            and isinstance(item.get("file"), str)
            and type(item.get("line")) is int
            and item["line"] >= 0
            and item.get("severity") in ("error", "warning")
            and isinstance(item.get("message"), str)
            and isinstance(item.get("ruleId"), str)
            and re.fullmatch(r"[A-Z]{3}-[0-9]{3}", item["ruleId"]) is not None
        )
        if not valid:
            reject(f"{description} entry {index} has an invalid shape")
    return report


def verify_snapshots(paths):
    for path, expected, limit, description in paths:
        _, observed = read_bounded(path, limit, description)
        if observed != expected:
            reject(f"{description} changed during contextlint: {path}")


def sanitize(text, workspace, run_root):
    stable = text.replace(run_root, "<private-probe>")
    stable = stable.replace(workspace, "<workspace>")
    return stable


def cleanup_private_root(root):
    if root is None:
        return
    for name in ("contextlint.config.json", "project.config.json", "probe.md"):
        path = os.path.join(root, name)
        if os.path.lexists(path):
            os.unlink(path)
    for name in ("home", "tmp", "xdg-cache"):
        path = os.path.join(root, name)
        if os.path.lexists(path):
            os.rmdir(path)
    os.rmdir(root)


def main():
    global active_workspace, private_run_root, cleaning, reported_signal
    if len(sys.argv) < 6:
        reject("invalid adapter arguments")
    node_name = sys.argv[1]
    tool_name = sys.argv[2]
    indicator_argument = sys.argv[3]
    payload = sys.argv[4:]
    if payload.count(MARKER) != 1 or payload[0] != MARKER:
        reject("forwarded arguments are unsupported and file marker is invalid")
    candidates = payload[1:]
    if not candidates:
        reject("runner selected zero candidate files")

    node_program = resolve_program(node_name, "Node executable")
    tool_program = resolve_program(tool_name, "contextlint executable")
    graph, cli_entry = validate_package_graph(tool_program)

    lexical_indicator = os.path.abspath(indicator_argument)
    if os.path.basename(lexical_indicator) != "contextlint.config.json":
        reject(f"invalid workspace indicator: {indicator_argument}")
    indicator = os.path.realpath(lexical_indicator)
    if lexical_indicator != indicator:
        reject("workspace indicator traverses a symbolic link")
    workspace = os.path.dirname(indicator)
    active_workspace = workspace
    reject_glob_magic_path(indicator, "workspace indicator")
    config_bytes, config_identity = read_bounded(
        indicator, MAX_CONFIG_BYTES, "contextlint.config.json"
    )
    validate_config(config_bytes)

    inventory = inventory_workspace(workspace)
    inventory_paths = [path for path, _ in inventory]
    inventory_set = set(inventory_paths)
    candidate_paths = []
    for candidate in candidates:
        absolute = os.path.abspath(candidate)
        reject_glob_magic_path(absolute, "runner candidate")
        canonical = os.path.realpath(absolute)
        if absolute != canonical or canonical not in inventory_set:
            reject(f"runner candidate is outside the physical Markdown inventory: {candidate}")
        candidate_paths.append(canonical)
    if len(set(candidate_paths)) != len(candidate_paths):
        reject("runner candidate list contains duplicates")

    snapshots = [(indicator, config_identity, MAX_CONFIG_BYTES, "contextlint.config.json")]
    snapshots.extend(
        (path, identity, MAX_FILE_BYTES, "Markdown file")
        for path, identity in inventory
    )

    run_root = None
    result = None
    try:
        run_root = create_private_run_root(workspace)
        private_run_root = run_root
        probe_config = os.path.join(run_root, "contextlint.config.json")
        project_config = os.path.join(run_root, "project.config.json")
        probe_document = os.path.join(run_root, "probe.md")
        write_private_file(probe_config, PROBE_CONFIG)
        write_private_file(project_config, config_bytes)
        write_private_file(probe_document, PROBE_DOCUMENT)
        private_config_bytes, _ = read_bounded(
            project_config, MAX_CONFIG_BYTES, "private contextlint.config.json copy"
        )
        if private_config_bytes != config_bytes:
            reject("private contextlint.config.json copy changed while being created")
        environment = child_environment(run_root)

        probe_args = node_arguments(
            node_program,
            cli_entry,
            (graph, run_root),
            probe_config,
            run_root,
            (probe_document,),
        )
        probe_status, probe_stdout, probe_stderr = run_child(
            probe_args, run_root, environment
        )
        probe_report = parse_report(probe_stdout, "private completion report")
        if probe_status != 1 or probe_stderr or probe_report != PROBE_REPORT:
            reject(
                "private SEC-001 completion probe did not return its exact pinned result"
            )

        command_args = node_arguments(
            node_program,
            cli_entry,
            (graph, workspace, run_root),
            project_config,
            workspace,
            inventory_paths,
        )
        status, stdout_bytes, stderr_bytes = run_child(
            command_args, workspace, environment
        )
        verify_snapshots(snapshots)

        if status in (0, 1):
            if stderr_bytes:
                reject("contextlint emitted stderr with a lint status")
            report = parse_report(stdout_bytes, "project completion report")
            has_errors = any(item["severity"] == "error" for item in report)
            if (status == 1) != has_errors:
                reject("contextlint exit status contradicts its JSON severities")
            relative_inventory = {
                os.path.relpath(path, workspace).replace(os.sep, "/")
                for path in inventory_paths
            }
            for item in report:
                if item["file"] != "(project)" and item["file"] not in relative_inventory:
                    reject(
                        f"contextlint attributed a diagnostic outside the inventory: {item['file']}"
                    )
                item["message"] = sanitize(item["message"], workspace, run_root)
            report.sort(
                key=lambda item: (
                    item["file"], item["line"], item["ruleId"],
                    item["severity"], item["message"],
                )
            )
            stable = json.dumps(
                report, ensure_ascii=False, sort_keys=True, separators=(",", ":")
            ) + "\n"
            result = (1 if report else 0, stable.encode("utf-8"), b"")
        else:
            stdout = sanitize(stdout_bytes.decode("utf-8", "replace"), workspace, run_root)
            stderr = sanitize(stderr_bytes.decode("utf-8", "replace"), workspace, run_root)
            diagnostic = stdout.encode("utf-8") + stderr.encode("utf-8")
            diagnostic += (
                f"velvet-glove-contextlint: contextlint exited with operational status {status}\n"
            ).encode("utf-8")
            result = (2, b"", diagnostic)
    finally:
        primary_error = sys.exc_info()[1]
        cleanup_error = stop_child()
        cleaning = True
        try:
            if run_root is not None:
                cleanup_private_root(run_root)
        except OSError as error:
            cleanup_failure = AdapterFailure(
                "cannot remove private completion-probe root: "
                + normalize_private_error(error, run_root)
            )
            cleanup_error = append_adapter_error(cleanup_error, cleanup_failure)
        finally:
            cleaning = False
        if cleanup_error is not None:
            if isinstance(primary_error, AdapterSignal):
                reported_signal = primary_error.signum
            if primary_error is not None:
                raise append_adapter_error(primary_error, cleanup_error)
            raise cleanup_error
    if pending_signal is not None:
        raise AdapterSignal(pending_signal)
    if result is None:
        reject("contextlint adapter produced no result")
    return result


previous_handlers = {}
adapter_error = None
result = None
try:
    for signum in handled_signals:
        previous_handlers[signum] = signal.signal(signum, forward_signal)
    result = main()
except AdapterSignal as error:
    adapter_error = append_adapter_error(error, stop_child(error.signum))
    reported_signal = error.signum
except AdapterFailure as error:
    adapter_error = append_adapter_error(error, stop_child())
except BaseException as error:
    adapter_error = append_adapter_error(
        RuntimeError(f"adapter failure: {error}"), stop_child()
    )
finally:
    cleaning = True
    blocked_mask = None
    try:
        try:
            blocked_mask = signal.pthread_sigmask(signal.SIG_BLOCK, handled_signals)
        except (OSError, ValueError) as error:
            adapter_error = append_adapter_error(
                adapter_error, AdapterFailure(f"cannot block cleanup signals: {error}")
            )
        adapter_error = apply_pending_signal(adapter_error)
        if blocked_mask is not None:
            while True:
                adapter_error, drained = drain_blocked_signals(adapter_error)
                if not drained:
                    break
    finally:
        # Keep these signals blocked through diagnostics and process exit.
        # Unblocking after restoring default handlers would reopen the
        # post-cleanup termination window closed by this cutoff.
        try:
            for signum, handler in previous_handlers.items():
                try:
                    signal.signal(signum, handler)
                except (OSError, ValueError):
                    pass
        finally:
            cleaning = False

if adapter_error is not None:
    message = normalize_private_error(adapter_error, private_run_root)
    if active_workspace is not None:
        message = message.replace(active_workspace, "<workspace>")
    print(f"velvet-glove-contextlint: {message}", file=sys.stderr)
    raise SystemExit(2)
if result is None:
    print("velvet-glove-contextlint: adapter produced no result", file=sys.stderr)
    raise SystemExit(2)
status, stdout_bytes, stderr_bytes = result
if stdout_bytes:
    sys.stdout.buffer.write(stdout_bytes)
if stderr_bytes:
    sys.stderr.buffer.write(stderr_bytes)
raise SystemExit(status)

import json
import math
import os
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time

MARKER = "__VELVET_GLOVE_DCLINT_FILES__"
INPUT_LIMIT = 64 * 1024 * 1024
WORKSPACE_LIMIT = 128 * 1024 * 1024
CONFIG_LIMIT = 1024 * 1024
OUTPUT_LIMIT = 32 * 1024 * 1024
MAX_FILES = 4096
MAX_WORKSPACE_FILES = 8192
MAX_WORKSPACE_DIRECTORIES = 8192
SKIPPED_DIRECTORIES = {".git", ".velvet-glove", "node" + "_modules", "target"}
HANDLED_SIGNALS = (signal.SIGHUP, signal.SIGINT, signal.SIGTERM)
VALIDATION_RULES = {"invalid-yaml", "invalid-schema", "unknown-error"}
UNSAFE_WRITE_RULES = {"no-version-field"}
RULE_FIXABILITY = {
    "no-build-and-image": False,
    "no-duplicate-container-names": False,
    "no-duplicate-exported-ports": False,
    "no-quotes-in-volumes": True,
    "no-unbound-port-interfaces": False,
    "no-version-field": False,
    "require-project-name-field": False,
    "require-quotes-in-ports": True,
    "service-container-name-regex": False,
    "service-dependencies-alphabetical-order": True,
    "service-image-require-explicit-tag": False,
    "service-keys-order": True,
    "service-ports-alphabetical-order": True,
    "services-alphabetical-order": True,
    "top-level-properties-order": True,
    "invalid-yaml": False,
    "invalid-schema": False,
    "unknown-error": False,
}
SERVICE_KEY_DEFAULT_GROUPS = {
    "Core Definitions": ["image", "build", "container_name"],
    "Service Dependencies": ["depends_on"],
    "Data Management and Configuration": [
        "volumes",
        "volumes_from",
        "configs",
        "secrets",
    ],
    "Environment Configuration": ["environment", "env_file"],
    "Networking": ["ports", "networks", "network_mode", "extra_hosts"],
    "Runtime Behavior": [
        "command",
        "entrypoint",
        "working_dir",
        "restart",
        "healthcheck",
    ],
    "Operational Metadata": ["logging", "labels"],
    "Security and Execution Context": ["user", "isolation"],
    "Other": [],
}
SERVICE_KEY_GROUPS = set(SERVICE_KEY_DEFAULT_GROUPS)
TOP_LEVEL_ORDER = (
    "x-properties",
    "version",
    "name",
    "include",
    "services",
    "models",
    "networks",
    "volumes",
    "secrets",
    "configs",
)
TOP_LEVEL_KEYS = set(TOP_LEVEL_ORDER)


class ContractError(Exception):
    pass


class AdapterSignal(BaseException):
    def __init__(self, signum):
        super().__init__(f"received signal {signum}")
        self.signum = signum


def reject(message):
    raise ContractError(message)


def safe_text(value, label, allow_empty=False):
    if not isinstance(value, str) or (not value and not allow_empty):
        reject(f"{label} is not a {'possibly empty' if allow_empty else 'nonempty'} string")
    if "\0" in value or "\n" in value or "\r" in value:
        reject(f"{label} contains a control character")
    try:
        value.encode("utf-8")
    except UnicodeError as error:
        reject(f"{label} is not UTF-8 encodable: {error}")
    return value


def safe_path_text(value, label):
    value = safe_text(value, label)
    if any(ord(character) < 0x20 or ord(character) == 0x7F for character in value):
        reject(f"{label} contains a control character")
    return value


def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key {key!r}")
        result[key] = value
    return result


def invalid_constant(value):
    raise ValueError(f"non-finite JSON number {value}")


def parse_json(raw, label):
    try:
        text = raw.decode("utf-8")
        return json.loads(
            text,
            object_pairs_hook=strict_object,
            parse_constant=invalid_constant,
        )
    except (UnicodeError, ValueError, json.JSONDecodeError) as error:
        reject(f"{label} is not strict UTF-8 JSON: {error}")


def validate_json_tree(value, label, depth=0):
    if depth > 32:
        reject(f"{label} exceeds the JSON nesting limit")
    if value is None or isinstance(value, (str, bool)):
        return
    if type(value) is int:
        return
    if type(value) is float:
        if not math.isfinite(value):
            reject(f"{label} contains a non-finite number")
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            validate_json_tree(item, f"{label}[{index}]", depth + 1)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            safe_text(key, f"{label} key")
            validate_json_tree(item, f"{label}.{key}", depth + 1)
        return
    reject(f"{label} contains an unsupported JSON value")


def string_list(value, label, allowed=None):
    if not isinstance(value, list) or not value:
        reject(f"{label} must be a nonempty array")
    result = []
    for index, item in enumerate(value):
        item = safe_text(item, f"{label}[{index}]")
        if allowed is not None and item not in allowed:
            reject(f"{label}[{index}] has unsupported value {item!r}")
        result.append(item)
    if len(set(result)) != len(result):
        reject(f"{label} contains duplicate values")
    return result


def validate_rule_options(rule, options):
    if not isinstance(options, dict):
        reject(f"dclint rule {rule!r} options are not an object")
    if rule == "no-build-and-image":
        unknown = set(options) - {"checkPullPolicy"}
        if unknown:
            reject(f"dclint rule {rule!r} has unknown options: {sorted(unknown)!r}")
        if "checkPullPolicy" in options and not isinstance(options["checkPullPolicy"], bool):
            reject("dclint checkPullPolicy option is not boolean")
    elif rule == "require-quotes-in-ports":
        unknown = set(options) - {"quoteType", "portsSections"}
        if unknown:
            reject(f"dclint rule {rule!r} has unknown options: {sorted(unknown)!r}")
        if "quoteType" in options and options["quoteType"] not in ("single", "double"):
            reject("dclint quoteType option must be 'single' or 'double'")
        if "portsSections" in options:
            string_list(options["portsSections"], "dclint portsSections", {"ports", "expose"})
    elif rule == "service-image-require-explicit-tag":
        unknown = set(options) - {"prohibitedTags"}
        if unknown:
            reject(f"dclint rule {rule!r} has unknown options: {sorted(unknown)!r}")
        if "prohibitedTags" in options:
            string_list(options["prohibitedTags"], "dclint prohibitedTags")
    elif rule == "service-keys-order":
        unknown = set(options) - {"groups", "groupOrder"}
        if unknown:
            reject(f"dclint rule {rule!r} has unknown options: {sorted(unknown)!r}")
        if "groups" in options:
            groups = options["groups"]
            if not isinstance(groups, dict):
                reject("dclint service-key groups option is not an object")
            effective_groups = dict(SERVICE_KEY_DEFAULT_GROUPS)
            for group, keys in groups.items():
                safe_text(group, "dclint service-key group")
                if group not in SERVICE_KEY_GROUPS:
                    reject(f"dclint service-key group is unsupported: {group!r}")
                effective_groups[group] = string_list(
                    keys, f"dclint service-key group {group!r}"
                )
            assigned_groups = {}
            for group, keys in effective_groups.items():
                for key in keys:
                    previous = assigned_groups.get(key)
                    if previous is not None:
                        reject(
                            f"dclint service key {key!r} is assigned to multiple groups: "
                            f"{previous!r} and {group!r}"
                        )
                    assigned_groups[key] = group
        if "groupOrder" in options:
            string_list(options["groupOrder"], "dclint groupOrder", SERVICE_KEY_GROUPS)
    elif rule == "top-level-properties-order":
        unknown = set(options) - {"customOrder"}
        if unknown:
            reject(f"dclint rule {rule!r} has unknown options: {sorted(unknown)!r}")
        if "customOrder" in options:
            order = string_list(
                options["customOrder"], "dclint customOrder", TOP_LEVEL_KEYS
            )
            if set(order) != TOP_LEVEL_KEYS:
                reject(
                    "dclint customOrder must be an exact permutation of the "
                    "pinned Compose top-level key order"
                )
    elif options:
        reject(f"dclint rule {rule!r} does not have controlled options")


def validate_config(config):
    if not isinstance(config, dict):
        reject("dclint config root is not an object")
    unknown = set(config) - {"$schema", "rules", "quiet", "debug", "exclude"}
    if unknown:
        reject(f"dclint config has unknown or executable-loading keys: {sorted(unknown)!r}")
    if "$schema" in config:
        safe_text(config["$schema"], "dclint config $schema")
    for name in ("quiet", "debug"):
        if name in config and config[name] is not False:
            reject(f"dclint config {name} must be false to preserve controlled diagnostics")
    if "exclude" in config and config["exclude"] != []:
        reject("dclint config exclude must be empty to preserve selected-file scope")
    rules = config.get("rules", {})
    if not isinstance(rules, dict):
        reject("dclint config rules is not an object")
    for rule, value in rules.items():
        safe_text(rule, "dclint config rule name")
        if rule not in RULE_FIXABILITY or rule in VALIDATION_RULES:
            reject(f"dclint config rule is unsupported: {rule!r}")
        if type(value) is int and value in (0, 1, 2):
            if rule in UNSAFE_WRITE_RULES and value != 0:
                reject(
                    f"dclint rule {rule!r} cannot be enabled because its "
                    "3.1.0 fixer can delete nested extension data"
                )
            continue
        if (
            isinstance(value, list)
            and len(value) == 2
            and type(value[0]) is int
            and value[0] in (0, 1, 2)
        ):
            if rule in UNSAFE_WRITE_RULES and value[0] != 0:
                reject(
                    f"dclint rule {rule!r} cannot be enabled because its "
                    "3.1.0 fixer can delete nested extension data"
                )
            validate_rule_options(rule, value[1])
            continue
        reject(f"dclint config rule {rule!r} has an unsupported value")


def normalize_config(config):
    validate_config(config)
    rules = config.setdefault("rules", {})
    rules.setdefault("no-version-field", 0)
    rule = "top-level-properties-order"
    safe_options = {"customOrder": list(TOP_LEVEL_ORDER)}
    value = rules.get(rule)
    if value is None:
        rules[rule] = [1, safe_options]
    elif type(value) is int:
        if value in (1, 2):
            rules[rule] = [value, safe_options]
    else:
        severity, options = value
        if severity in (1, 2) and "customOrder" not in options:
            normalized_options = dict(options)
            normalized_options["customOrder"] = list(TOP_LEVEL_ORDER)
            rules[rule] = [severity, normalized_options]
    return config


def normalized_config_bytes(raw, label):
    config = normalize_config(parse_json(raw, label))
    encoded = (
        json.dumps(config, ensure_ascii=True, separators=(",", ":")) + "\n"
    ).encode("ascii")
    if len(encoded) > CONFIG_LIMIT:
        reject(f"{label} exceeds the normalized {CONFIG_LIMIT}-byte limit")
    return encoded


def inspect_file(path, label, limit):
    if os.path.realpath(path) != path:
        reject(f"{label} traverses a symlink: {path}")
    try:
        info = os.lstat(path)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
            reject(f"{label} is not a unique regular file: {path}")
        flags = os.O_RDONLY
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(path, flags)
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino) != (info.st_dev, info.st_ino)
        ):
            os.close(descriptor)
            reject(f"{label} changed identity while opening: {path}")
        with os.fdopen(descriptor, "rb") as source:
            data = source.read(limit + 1)
            final = os.fstat(source.fileno())
    except OSError as error:
        reject(f"cannot inspect {label} {path}: {error}")
    if len(data) > limit:
        reject(f"{label} exceeds the {limit}-byte limit: {path}")
    stable = ("st_dev", "st_ino", "st_mode", "st_nlink", "st_size", "st_mtime_ns")
    if any(getattr(opened, field) != getattr(final, field) for field in stable):
        reject(f"{label} changed while it was read: {path}")
    return {
        "path": path,
        "dev": final.st_dev,
        "ino": final.st_ino,
        "mode": stat.S_IMODE(final.st_mode),
        "mtime_ns": final.st_mtime_ns,
        "data": data,
    }


def inspect_directory(path, label):
    safe_path_text(path, label)
    try:
        initial = os.lstat(path)
        if stat.S_ISLNK(initial.st_mode) or not stat.S_ISDIR(initial.st_mode):
            reject(f"{label} is not a real directory: {path}")
        flags = os.O_RDONLY
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        if hasattr(os, "O_DIRECTORY"):
            flags |= os.O_DIRECTORY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(path, flags)
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISDIR(opened.st_mode)
            or (opened.st_dev, opened.st_ino) != (initial.st_dev, initial.st_ino)
        ):
            os.close(descriptor)
            reject(f"{label} changed while it was opened: {path}")
        os.close(descriptor)
    except OSError as error:
        reject(f"cannot inspect {label} {path}: {error}")
    return {
        "path": path,
        "dev": opened.st_dev,
        "ino": opened.st_ino,
        "mode": stat.S_IMODE(opened.st_mode),
    }


def retained_relative(project_root, path):
    return os.path.relpath(path, project_root).replace(os.sep, "/")


def scan_workspace(project_root):
    files = {}
    directories = {}
    total = 0

    def walk_error(error):
        reject(f"cannot walk retained workspace: {error}")

    for directory, child_directories, names in os.walk(
        project_root, followlinks=False, onerror=walk_error
    ):
        relative_directory = retained_relative(project_root, directory)
        if len(directories) >= MAX_WORKSPACE_DIRECTORIES:
            reject(
                f"retained workspace contains more than {MAX_WORKSPACE_DIRECTORIES} directories"
            )
        directories[relative_directory] = inspect_directory(
            directory, "retained workspace directory"
        )
        retained_children = []
        for name in child_directories:
            path = os.path.join(directory, name)
            safe_path_text(path, "retained workspace path")
            if name in SKIPPED_DIRECTORIES:
                continue
            if os.path.islink(path):
                reject(f"retained workspace contains a symlink directory: {path}")
            retained_children.append(name)
        child_directories[:] = retained_children
        for name in names:
            path = os.path.join(directory, name)
            safe_path_text(path, "retained workspace path")
            relative = retained_relative(project_root, path)
            snapshot = inspect_file(path, "retained workspace file", INPUT_LIMIT)
            total += len(snapshot["data"])
            if len(files) >= MAX_WORKSPACE_FILES:
                reject(f"retained workspace contains more than {MAX_WORKSPACE_FILES} files")
            if total > WORKSPACE_LIMIT:
                reject(
                    f"retained workspace files exceed the {WORKSPACE_LIMIT}-byte aggregate limit"
                )
            files[relative] = snapshot
    return files, directories


def workspace_diff(before, before_directories, after, after_directories):
    before_paths = set(before)
    after_paths = set(after)
    added = sorted(after_paths - before_paths)
    removed = sorted(before_paths - after_paths)
    changed = sorted(
        relative
        for relative in before_paths.intersection(after_paths)
        if before[relative]["data"] != after[relative]["data"]
    )
    touched = sorted(
        relative
        for relative in before_paths.intersection(after_paths)
        if relative not in changed and before[relative] != after[relative]
    )
    before_directory_paths = set(before_directories)
    after_directory_paths = set(after_directories)
    added_directories = sorted(after_directory_paths - before_directory_paths)
    removed_directories = sorted(before_directory_paths - after_directory_paths)
    touched_directories = sorted(
        relative
        for relative in before_directory_paths.intersection(after_directory_paths)
        if before_directories[relative]["mode"] != after_directories[relative]["mode"]
    )
    return (
        added,
        removed,
        changed,
        touched,
        added_directories,
        removed_directories,
        touched_directories,
    )


def workspace_change_summary(diff):
    labels = (
        "added files",
        "removed files",
        "changed files",
        "metadata-only files",
        "added directories",
        "removed directories",
        "mode-changed directories",
    )
    parts = []
    for label, paths in zip(labels, diff):
        if paths:
            parts.append(f"{label}: {', '.join(paths[:8])}")
    return "; ".join(parts) if parts else "no retained workspace changes"


def workspace_path(project_root, relative):
    if relative == ".":
        return project_root
    return os.path.join(project_root, relative.replace("/", os.sep))


def atomic_write(path, data, mode):
    descriptor, temporary_path = tempfile.mkstemp(
        prefix=".velvet-glove-dclint-", dir=os.path.dirname(path)
    )
    try:
        os.fchmod(descriptor, mode)
        with os.fdopen(descriptor, "wb", closefd=True) as destination:
            descriptor = -1
            destination.write(data)
            destination.flush()
            os.fsync(destination.fileno())
        os.replace(temporary_path, path)
    except BaseException:
        if descriptor >= 0:
            os.close(descriptor)
        try:
            os.unlink(temporary_path)
        except OSError:
            pass
        raise


def make_directory_traversable(path):
    initial = os.lstat(path)
    if stat.S_ISLNK(initial.st_mode) or not stat.S_ISDIR(initial.st_mode):
        raise ValueError(f"path is not a real directory: {path}")
    current_mode = stat.S_IMODE(initial.st_mode)
    temporary_mode = current_mode | stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR
    if temporary_mode != current_mode:
        os.chmod(path, temporary_mode, follow_symlinks=False)
        restored = os.lstat(path)
        if (
            stat.S_ISLNK(restored.st_mode)
            or not stat.S_ISDIR(restored.st_mode)
            or (restored.st_dev, restored.st_ino) != (initial.st_dev, initial.st_ino)
            or stat.S_IMODE(restored.st_mode) != temporary_mode
        ):
            raise ValueError(f"directory changed while making it traversable: {path}")


def set_directory_mode(path, mode):
    flags = os.O_RDONLY
    if hasattr(os, "O_CLOEXEC"):
        flags |= os.O_CLOEXEC
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags)
    try:
        opened = os.fstat(descriptor)
        if not stat.S_ISDIR(opened.st_mode):
            raise ValueError(f"path is not a real directory: {path}")
        os.fchmod(descriptor, mode)
        restored = os.fstat(descriptor)
        if (
            (restored.st_dev, restored.st_ino) != (opened.st_dev, opened.st_ino)
            or stat.S_IMODE(restored.st_mode) != mode
        ):
            raise ValueError(f"directory changed while restoring its mode: {path}")
    finally:
        os.close(descriptor)


def rollback_inventory(project_root, errors):
    entries = {}
    directories = set()

    def walk_error(error):
        errors.append(f"walk retained workspace for rollback: {error}")

    for directory, child_directories, names in os.walk(
        project_root, followlinks=False, onerror=walk_error
    ):
        relative_directory = retained_relative(project_root, directory)
        directories.add(relative_directory)
        retained_children = []
        for name in child_directories:
            path = os.path.join(directory, name)
            if name in SKIPPED_DIRECTORIES:
                continue
            relative = retained_relative(project_root, path)
            try:
                info = os.lstat(path)
                if stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode):
                    make_directory_traversable(path)
                    retained_children.append(name)
                else:
                    entries[relative] = path
            except (OSError, ValueError) as error:
                errors.append(f"inspect rollback entry {relative!r}: {error}")
        child_directories[:] = retained_children
        for name in names:
            path = os.path.join(directory, name)
            entries[retained_relative(project_root, path)] = path
    return entries, directories


def restore_workspace(project_root, before, before_directories):
    errors = []
    try:
        if not os.path.lexists(project_root):
            os.mkdir(project_root, mode=0o700)
        make_directory_traversable(project_root)
    except (OSError, ValueError) as error:
        errors.append(f"restore project root: {error}")
        return "; ".join(errors)

    entries, current_directories = rollback_inventory(project_root, errors)
    for relative, path in sorted(entries.items(), reverse=True):
        keep = False
        if relative in before:
            try:
                info = os.lstat(path)
                keep = stat.S_ISREG(info.st_mode) and not stat.S_ISLNK(info.st_mode) and info.st_nlink == 1
            except OSError:
                pass
        if keep:
            continue
        try:
            os.unlink(path)
        except OSError as error:
            errors.append(f"remove rollback entry {relative!r}: {error}")

    for relative in sorted(
        current_directories - set(before_directories),
        key=lambda item: (item.count("/"), item),
        reverse=True,
    ):
        path = workspace_path(project_root, relative)
        try:
            os.rmdir(path)
        except OSError as error:
            errors.append(f"remove rollback directory {relative!r}: {error}")

    for relative in sorted(
        set(before_directories) - current_directories,
        key=lambda item: (item.count("/"), item),
    ):
        path = workspace_path(project_root, relative)
        try:
            os.mkdir(path, mode=0o700)
        except OSError as error:
            errors.append(f"recreate rollback directory {relative!r}: {error}")

    for relative, snapshot in sorted(before.items()):
        path = workspace_path(project_root, relative)
        try:
            current = None
            if os.path.lexists(path):
                try:
                    current = inspect_file(path, "rollback file", INPUT_LIMIT)
                except ContractError:
                    os.unlink(path)
            if (
                current is None
                or current["data"] != snapshot["data"]
                or current["mode"] != snapshot["mode"]
            ):
                atomic_write(path, snapshot["data"], snapshot["mode"])
                current = inspect_file(path, "restored file", INPUT_LIMIT)
            if current["mtime_ns"] != snapshot["mtime_ns"]:
                flags = os.O_RDONLY
                if hasattr(os, "O_CLOEXEC"):
                    flags |= os.O_CLOEXEC
                if hasattr(os, "O_NOFOLLOW"):
                    flags |= os.O_NOFOLLOW
                descriptor = os.open(path, flags)
                try:
                    opened = os.fstat(descriptor)
                    if (
                        not stat.S_ISREG(opened.st_mode)
                        or opened.st_nlink != 1
                        or (opened.st_dev, opened.st_ino) != (current["dev"], current["ino"])
                    ):
                        raise ValueError(f"file changed before restoring its mtime: {path}")
                    os.utime(
                        descriptor,
                        ns=(opened.st_atime_ns, snapshot["mtime_ns"]),
                    )
                    restored = os.fstat(descriptor)
                    if restored.st_mtime_ns != snapshot["mtime_ns"]:
                        raise ValueError(f"file changed while restoring its mtime: {path}")
                finally:
                    os.close(descriptor)
        except (OSError, ValueError, ContractError) as error:
            errors.append(f"restore file {relative!r}: {error}")

    for relative in sorted(
        before_directories,
        key=lambda item: (item.count("/"), item),
        reverse=True,
    ):
        path = workspace_path(project_root, relative)
        try:
            current = inspect_directory(path, "rollback directory")
            if current["mode"] != before_directories[relative]["mode"]:
                set_directory_mode(path, before_directories[relative]["mode"])
        except (OSError, ValueError, ContractError) as error:
            errors.append(f"restore directory {relative!r}: {error}")

    try:
        restored, restored_directories = scan_workspace(project_root)
        if set(restored) != set(before):
            errors.append("restored retained workspace paths differ from the baseline")
        else:
            for relative, snapshot in before.items():
                current = restored[relative]
                for key in ("data", "mode", "mtime_ns"):
                    if current[key] != snapshot[key]:
                        errors.append(
                            f"restored file {relative!r} {key} differs from the baseline"
                        )
        if set(restored_directories) != set(before_directories):
            errors.append(
                "restored retained workspace directory topology differs from the baseline"
            )
        else:
            for relative, snapshot in before_directories.items():
                if restored_directories[relative]["mode"] != snapshot["mode"]:
                    errors.append(
                        f"restored directory {relative!r} mode differs from the baseline"
                    )
    except (OSError, ValueError, ContractError) as error:
        errors.append(f"verify restored retained workspace: {error}")
    return "; ".join(errors) if errors else None


def snapshot_files(paths):
    snapshots = []
    total = 0
    for path in paths:
        snapshot = inspect_file(path, "selected file", INPUT_LIMIT)
        total += len(snapshot["data"])
        if total > INPUT_LIMIT:
            reject(f"selected files exceed the {INPUT_LIMIT}-byte aggregate limit")
        snapshots.append(snapshot)
    return snapshots


def validate_project_root(requested):
    safe_path_text(requested, "project root")
    if not os.path.isabs(requested) or os.path.normpath(requested) != requested:
        reject(f"project root is not normalized and absolute: {requested}")
    if os.path.realpath(requested) != requested:
        reject(f"project root traverses a symlink: {requested}")
    try:
        info = os.lstat(requested)
        if not stat.S_ISDIR(info.st_mode):
            reject(f"project root is not a real directory: {requested}")
        with os.scandir(requested):
            pass
    except OSError as error:
        reject(f"cannot inspect project root {requested}: {error}")
    return requested


def validate_selected_files(project_root, requested_files):
    if not requested_files:
        reject("empty file selection")
    if len(requested_files) > MAX_FILES:
        reject(f"selected file count exceeds the {MAX_FILES}-file limit")
    if requested_files != sorted(requested_files):
        reject("selected files are not in stable lexical order")
    seen_paths = set()
    seen_identities = set()
    normalized = []
    for requested in requested_files:
        safe_path_text(requested, "selected path")
        if not os.path.isabs(requested) or os.path.normpath(requested) != requested:
            reject(f"selected path is not normalized and absolute: {requested}")
        try:
            inside = os.path.commonpath((project_root, requested)) == project_root
        except ValueError:
            inside = False
        if not inside:
            reject(f"selected path escapes the project root: {requested}")
        snapshot = inspect_file(requested, "selected file", INPUT_LIMIT)
        identity = (snapshot["dev"], snapshot["ino"])
        if requested in seen_paths or identity in seen_identities:
            reject(f"selected path is repeated or aliases another file: {requested}")
        seen_paths.add(requested)
        seen_identities.add(identity)
        normalized.append(requested)
    snapshot_files(normalized)
    return normalized


def validate_private_config(path, expected_data):
    snapshot = inspect_file(path, "generated config", CONFIG_LIMIT)
    if snapshot["mode"] != 0o600:
        reject(f"generated config is not mode 0600: {path}")
    if snapshot["data"] != expected_data:
        reject("generated config does not match its validated source bytes")
    if normalized_config_bytes(snapshot["data"], "generated config") != snapshot["data"]:
        reject("generated config is not in its normalized safe form")
    return snapshot


def create_private_config(contents, project_root):
    temporary = os.environ.get("TMPDIR")
    if not temporary:
        reject("TMPDIR must name an existing absolute directory")
    safe_path_text(temporary, "TMPDIR")
    if not os.path.isabs(temporary):
        reject("TMPDIR must name an existing absolute directory")
    try:
        temporary = os.path.realpath(temporary)
        safe_path_text(temporary, "resolved TMPDIR")
        if not os.path.isabs(temporary) or os.path.normpath(temporary) != temporary:
            reject("resolved TMPDIR is not normalized and absolute")
        info = os.lstat(temporary)
        if not stat.S_ISDIR(info.st_mode):
            reject(f"TMPDIR is not a real directory: {temporary}")
        with os.scandir(temporary):
            pass
    except ContractError:
        raise
    except (OSError, ValueError):
        reject("TMPDIR must resolve to an existing accessible directory")
    try:
        inside_project = os.path.commonpath((project_root, temporary)) == project_root
    except ValueError:
        inside_project = False
    if inside_project:
        reject("TMPDIR must be outside the retained project root")
    directory = None
    try:
        directory = tempfile.mkdtemp(prefix="velvet-glove-dclint-", dir=temporary)
        os.chmod(directory, 0o700)
        path = os.path.join(directory, "config.json")
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(path, flags, 0o600)
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as destination:
            destination.write(contents)
            destination.flush()
            os.fsync(destination.fileno())
    except BaseException as error:
        cleanup_error = None
        if directory is not None:
            try:
                shutil.rmtree(directory)
            except OSError as caught:
                cleanup_error = caught
        message = sanitize_private_error(error, directory)
        if cleanup_error is not None:
            message += "; cannot remove private dclint config directory: " + sanitize_private_error(
                cleanup_error, directory
            )
        reject(message)
    validate_private_config(path, contents)
    return path, directory


def resolve_config(project_root, extra_args):
    if not extra_args:
        contents = normalized_config_bytes(b"{}\n", "default dclint config")
        path, directory = create_private_config(contents, project_root)
        return path, directory, validate_private_config(path, contents), None, None
    if len(extra_args) != 1:
        reject("only one explicit --config=<relative.json> argument is supported")
    argument = safe_path_text(extra_args[0], "extra argument")
    prefix = "--config="
    if not argument.startswith(prefix):
        reject(f"unsupported argument {argument!r}; only --config=<relative.json> is allowed")
    relative = argument[len(prefix) :]
    safe_path_text(relative, "config path")
    if (
        "\\" in relative
        or os.path.isabs(relative)
        or os.path.normpath(relative) != relative
        or relative in (".", "..")
        or relative.startswith("../")
        or not relative.endswith(".json")
    ):
        reject(f"config path is not a normalized in-project JSON path: {relative}")
    path = os.path.abspath(os.path.join(project_root, relative))
    try:
        inside = os.path.commonpath((project_root, path)) == project_root
    except ValueError:
        inside = False
    if not inside:
        reject(f"config path escapes the project root: {relative}")
    if any(component in SKIPPED_DIRECTORIES for component in relative.split("/")):
        reject("config path is beneath a retained-workspace skipped directory")
    snapshot = inspect_file(path, "config", CONFIG_LIMIT)
    contents = normalized_config_bytes(snapshot["data"], "dclint config")
    private_path, directory = create_private_config(contents, project_root)
    return (
        private_path,
        directory,
        validate_private_config(private_path, contents),
        path,
        snapshot,
    )


def resolve_executable(requested, label):
    safe_path_text(requested, f"requested {label} executable")
    candidate = shutil.which(requested)
    if candidate is None:
        reject(f"cannot resolve {label} executable {requested!r}")
    candidate = os.path.abspath(candidate)
    resolved = os.path.realpath(candidate)
    try:
        info = os.stat(resolved)
    except OSError as error:
        reject(f"cannot inspect resolved {label} executable {resolved}: {error}")
    if not stat.S_ISREG(info.st_mode) or not os.access(resolved, os.X_OK):
        reject(f"resolved {label} executable is not an executable regular file: {resolved}")
    return candidate, resolved


process = None
pending_signal = None
reported_signal = None
cleaning = True
output_total = 0


def signal_group(signum):
    if process is None:
        return
    try:
        os.killpg(process.pid, signum)
    except (OSError, ValueError):
        pass


def process_group_exists():
    if process is None:
        return False
    try:
        os.killpg(process.pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def sweep_process_group():
    if not process_group_exists():
        return False
    signal_group(signal.SIGKILL)
    deadline = time.monotonic() + 1
    while process_group_exists() and time.monotonic() < deadline:
        time.sleep(0.01)
    if process_group_exists():
        reject("cannot reap same-group descendants after child exit")
    return True


def stop_child(initial_signal=None):
    global process
    global cleaning
    child = process
    if child is None:
        return None
    failures = []
    prior_cleaning = cleaning
    cleaning = True
    try:
        try:
            running = child.poll() is None
        except (OSError, ValueError) as error:
            failures.append(f"cannot poll native child: {error}")
            running = True
        if running:
            signal_group(initial_signal if initial_signal is not None else signal.SIGTERM)
            try:
                child.wait(timeout=1)
            except subprocess.TimeoutExpired:
                pass
            except (OSError, ValueError) as error:
                failures.append(f"cannot stop native child gracefully: {error}")
        signal_group(signal.SIGKILL)
        try:
            child.wait(timeout=1)
        except (OSError, ValueError, subprocess.TimeoutExpired) as error:
            failures.append(f"cannot reap native child: {error}")
        try:
            deadline = time.monotonic() + 1
            while process_group_exists() and time.monotonic() < deadline:
                time.sleep(0.01)
            if process_group_exists():
                failures.append("native child process group survived SIGKILL")
        except (OSError, ValueError) as error:
            failures.append(f"cannot verify native child process-group cleanup: {error}")
    finally:
        process = None
        cleaning = prior_cleaning
    return "; ".join(failures) if failures else None


def forward_signal(signum, _frame):
    global pending_signal
    pending_signal = signum
    if process is not None and not cleaning:
        signal_group(signum)
        raise AdapterSignal(signum)


def append_adapter_error(primary, secondary):
    if primary is None:
        return secondary
    return ContractError(f"{primary}; {secondary}")


def apply_pending_signal(primary):
    global reported_signal
    if pending_signal is None or pending_signal == reported_signal:
        return primary
    reported_signal = pending_signal
    return append_adapter_error(primary, ContractError(f"received signal {pending_signal}"))


def drain_blocked_signals(primary):
    global pending_signal
    drained = False
    while True:
        queued = sorted(set(signal.sigpending()).intersection(HANDLED_SIGNALS), key=int)
        if not queued:
            return primary, drained
        pending_signal = int(signal.sigwait({queued[0]}))
        primary = apply_pending_signal(primary)
        drained = True


def sanitize_private_error(error, owned_directory):
    message = str(error)
    if owned_directory is not None:
        return message.replace(owned_directory, "<dclint-private>")
    if isinstance(error, OSError) and error.filename is not None:
        filename = os.fsdecode(error.filename)
        candidate = os.path.abspath(filename)
        parent = os.path.dirname(candidate)
        if os.path.basename(candidate).startswith("velvet-glove-dclint-"):
            message = message.replace(filename, "<dclint-private>")
        elif os.path.basename(parent).startswith("velvet-glove-dclint-"):
            message = message.replace(parent, "<dclint-private>")
    return message


def run_child(arguments, environment):
    global process
    global cleaning
    global output_total
    global pending_signal
    global reported_signal
    stdout_chunks = []
    stderr_chunks = []
    try:
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        if not hasattr(signal, "pthread_sigmask"):
            reject("Python does not support atomic signal masking around child spawn")
        previous_mask = signal.pthread_sigmask(signal.SIG_BLOCK, HANDLED_SIGNALS)
        try:
            queued = sorted(
                set(signal.sigpending()).intersection(HANDLED_SIGNALS), key=int
            )
            if queued:
                pending_signal = int(signal.sigwait({queued[0]}))
                raise AdapterSignal(pending_signal)
            process = subprocess.Popen(
                arguments,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=environment,
                start_new_session=True,
            )
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, previous_mask)
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        left_descendants = False
        leader_status = None
        with selectors.DefaultSelector() as selector:
            for stream, target in ((process.stdout, stdout_chunks), (process.stderr, stderr_chunks)):
                if stream is None:
                    reject("failed to capture dclint output")
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, target)
            while selector.get_map():
                if pending_signal is not None:
                    raise AdapterSignal(pending_signal)
                ready = selector.select(timeout=0.1)
                for key, _ in ready:
                    chunk = os.read(key.fileobj.fileno(), 65536)
                    if chunk:
                        output_total += len(chunk)
                        if output_total > OUTPUT_LIMIT:
                            reject(f"combined dclint output exceeded {OUTPUT_LIMIT} bytes")
                        key.data.append(chunk)
                    else:
                        selector.unregister(key.fileobj)
                        key.fileobj.close()
                if leader_status is None:
                    leader_status = process.poll()
                    if leader_status is not None:
                        cleaning = True
                        try:
                            left_descendants = sweep_process_group()
                        finally:
                            cleaning = False
        status = process.wait() if leader_status is None else leader_status
        if leader_status is None:
            cleaning = True
            try:
                left_descendants = sweep_process_group()
            finally:
                cleaning = False
        if left_descendants:
            reject("native dclint left same-group descendants after child exit")
        process = None
        if pending_signal is not None:
            raise AdapterSignal(pending_signal)
        return status, b"".join(stdout_chunks), b"".join(stderr_chunks)
    except AdapterSignal as error:
        reported_signal = error.signum
        cleanup_error = stop_child(error.signum)
        if cleanup_error is not None:
            reject(f"{error}; child cleanup failed: {cleanup_error}")
        raise
    except BaseException as error:
        cleanup_error = stop_child()
        if cleanup_error is not None:
            reject(f"{error}; child cleanup failed: {cleanup_error}")
        raise


def stable_first_line(raw, redactions):
    try:
        line = raw.decode("utf-8", "replace").splitlines()[0]
    except IndexError:
        return "no native diagnostic"
    for value, replacement in redactions:
        if value:
            line = line.replace(value, replacement)
    line = "".join(character if character.isprintable() else "?" for character in line)
    return line[:512] if line else "no native diagnostic"


def positive_integer(value, label, allow_zero=False):
    if type(value) is not int or value < (0 if allow_zero else 1):
        reject(f"{label} is not a valid integer")
    return value


def validate_message(message, label):
    if not isinstance(message, dict):
        reject(f"{label} is not an object")
    required = {
        "rule",
        "type",
        "category",
        "severity",
        "message",
        "line",
        "column",
        "fixable",
        "data",
    }
    allowed = required | {"endLine", "endColumn", "meta"}
    if set(message) < required or set(message) - allowed:
        reject(f"{label} has missing or unknown fields")
    rule = safe_text(message["rule"], f"{label}.rule")
    if rule not in RULE_FIXABILITY:
        reject(f"{label} reports unknown rule {rule!r}")
    if message["type"] not in ("error", "warning"):
        reject(f"{label}.type is unsupported")
    safe_text(message["category"], f"{label}.category")
    safe_text(message["severity"], f"{label}.severity")
    safe_text(message["message"], f"{label}.message")
    positive_integer(message["line"], f"{label}.line")
    positive_integer(message["column"], f"{label}.column")
    for name in ("endLine", "endColumn"):
        if name in message:
            positive_integer(message[name], f"{label}.{name}")
    if type(message["fixable"]) is not bool:
        reject(f"{label}.fixable is not boolean")
    if message["fixable"] != RULE_FIXABILITY[rule]:
        reject(f"{label} fixability disagrees with pinned dclint 3.1.0 rule semantics")
    validate_json_tree(message["data"], f"{label}.data")
    if "meta" in message:
        meta = message["meta"]
        if not isinstance(meta, dict) or set(meta) != {"description", "url"}:
            reject(f"{label}.meta does not have the pinned shape")
        safe_text(meta["description"], f"{label}.meta.description")
        safe_text(meta["url"], f"{label}.meta.url")
    if rule in VALIDATION_RULES and (
        message["type"] != "error" or message["fixable"] is not False
    ):
        reject(f"{label} validation diagnostic has ambiguous semantics")
    return rule


def validate_report(label, status, stdout_bytes, stderr_bytes, expected_files, redactions):
    if stderr_bytes:
        reject(
            f"native {label} emitted stderr instead of a controlled JSON report "
            f"(status {status}): {stable_first_line(stderr_bytes, redactions)}"
        )
    if status not in (0, 1):
        reject(f"native {label} returned unsupported status {status}")
    report = parse_json(stdout_bytes, f"native {label} report")
    if not isinstance(report, list) or len(report) != len(expected_files):
        reject(f"native {label} report does not cover the exact selected file count")
    fixable_files = []
    has_validation = False
    total_messages = 0
    for index, (record, expected_file) in enumerate(zip(report, expected_files)):
        record_label = f"native {label} report[{index}]"
        if not isinstance(record, dict) or set(record) != {
            "filePath",
            "messages",
            "errorCount",
            "warningCount",
            "fixableErrorCount",
            "fixableWarningCount",
        }:
            reject(f"{record_label} does not have the pinned dclint 3.1.0 shape")
        if record["filePath"] != expected_file:
            reject(f"{record_label} path does not match the requested file")
        messages = record["messages"]
        if not isinstance(messages, list):
            reject(f"{record_label}.messages is not an array")
        rules = [
            validate_message(message, f"{record_label}.messages[{message_index}]")
            for message_index, message in enumerate(messages)
        ]
        error_count = sum(message["type"] == "error" for message in messages)
        warning_count = sum(message["type"] == "warning" for message in messages)
        fixable_error_count = sum(
            message["type"] == "error" and message["fixable"] for message in messages
        )
        fixable_warning_count = sum(
            message["type"] == "warning" and message["fixable"] for message in messages
        )
        expected_counts = (
            error_count,
            warning_count,
            fixable_error_count,
            fixable_warning_count,
        )
        observed_counts = tuple(
            positive_integer(record[name], f"{record_label}.{name}", allow_zero=True)
            for name in (
                "errorCount",
                "warningCount",
                "fixableErrorCount",
                "fixableWarningCount",
            )
        )
        if observed_counts != expected_counts:
            reject(f"{record_label} counters disagree with its messages")
        if fixable_error_count + fixable_warning_count > 0:
            fixable_files.append(expected_file)
        if any(rule in VALIDATION_RULES for rule in rules):
            has_validation = True
        total_messages += len(messages)
    expected_status = 1 if total_messages else 0
    if status != expected_status:
        reject(
            f"native {label} status {status} disagrees with its complete report; "
            f"expected {expected_status}"
        )
    return report, fixable_files, has_validation


def native_arguments(tool, config_path, files, fix):
    arguments = [
        tool,
        "--formatter=json",
        "--color=false",
        "--max-warnings=0",
        f"--config={config_path}",
    ]
    if fix:
        arguments.append("--fix")
    arguments.extend(files)
    return arguments


def assert_config_unchanged(config_path, expected, label):
    if inspect_file(config_path, label, CONFIG_LIMIT) != expected:
        reject(f"{label} changed during native execution")


def assert_workspace_unchanged(
    label, project_root, expected_files, expected_directories
):
    observed_files, observed_directories = scan_workspace(project_root)
    diff = workspace_diff(
        expected_files,
        expected_directories,
        observed_files,
        observed_directories,
    )
    if any(diff):
        reject(f"{label} changed the retained workspace: {workspace_change_summary(diff)}")
    return observed_files, observed_directories


def execute():
    global output_total
    global cleaning
    global reported_signal
    if len(sys.argv) < 6 or sys.argv[4:].count(MARKER) != 1:
        reject("invalid adapter arguments")
    requested_tool = sys.argv[1]
    mode = sys.argv[2]
    project_root = validate_project_root(sys.argv[3])
    payload = sys.argv[4:]
    marker_index = payload.index(MARKER)
    extra_args = payload[:marker_index]
    files = validate_selected_files(project_root, payload[marker_index + 1 :])
    if mode not in ("verify", "fix"):
        reject("invalid adapter mode")
    if not all(
        hasattr(signal, name) for name in ("pthread_sigmask", "sigpending", "sigwait")
    ):
        reject("Python does not support the required atomic signal cleanup primitives")

    tool, resolved_tool = resolve_executable(requested_tool, "dclint")
    _, resolved_node = resolve_executable("node", "Node")
    environment = os.environ.copy()
    for name in tuple(environment):
        if (
            name.startswith("NODE_")
            or name.startswith("DYLD_")
            or name.startswith("LD_")
            or name in {"DEBUG", "DCLINT_CONFIG", "FORCE_COLOR"}
        ):
            environment.pop(name, None)
    environment.update(
        {
            "PATH": os.path.dirname(resolved_node) + os.pathsep + "/usr/bin:/bin",
            "LANG": "C",
            "LC_ALL": "C",
            "TZ": "UTC",
            "TERM": "dumb",
            "CI": "1",
            "NO_COLOR": "1",
            "CLICOLOR": "0",
            "FORCE_COLOR": "0",
            "NODE_NO_WARNINGS": "1",
        }
    )

    previous_handlers = {}
    config_path = None
    private_config_dir = None
    config_snapshot = None
    source_config_path = None
    source_config_snapshot = None
    baseline = None
    baseline_directories = None
    result = None
    error = None
    output_total = 0
    reported_signal = None
    try:
        for signum in HANDLED_SIGNALS:
            previous_handlers[signum] = signal.signal(signum, forward_signal)
        cleaning = False
        (
            config_path,
            private_config_dir,
            config_snapshot,
            source_config_path,
            source_config_snapshot,
        ) = resolve_config(project_root, extra_args)
        environment["TMPDIR"] = os.path.dirname(private_config_dir)
        if source_config_path is not None:
            assert_config_unchanged(
                source_config_path, source_config_snapshot, "source config"
            )
        baseline, baseline_directories = scan_workspace(project_root)
        selected_relatives = {
            path: retained_relative(project_root, path) for path in files
        }
        missing_selected = sorted(
            relative
            for relative in selected_relatives.values()
            if relative not in baseline
        )
        if missing_selected:
            reject(
                "selected files are outside the retained workspace: "
                + ", ".join(missing_selected)
            )
        assert_config_unchanged(
            config_path, config_snapshot, "controlled private config"
        )
        if source_config_path is not None:
            assert_config_unchanged(
                source_config_path, source_config_snapshot, "source config"
            )
        redactions = [
            (config_path, "<config>"),
            (resolved_tool, "<dclint>"),
            (resolved_node, "<node>"),
        ]
        preflight_status, preflight_stdout, preflight_stderr = run_child(
            native_arguments(tool, config_path, files, False), environment
        )
        assert_config_unchanged(
            config_path, config_snapshot, "controlled private config"
        )
        if source_config_path is not None:
            assert_config_unchanged(
                source_config_path, source_config_snapshot, "source config"
            )
        assert_workspace_unchanged(
            "dclint preflight", project_root, baseline, baseline_directories
        )
        preflight_report, fixable_files, has_validation = validate_report(
            "preflight",
            preflight_status,
            preflight_stdout,
            preflight_stderr,
            files,
            redactions,
        )

        if mode == "verify" or has_validation or not fixable_files:
            result = (preflight_status, preflight_report)
        else:
            before_write, before_write_directories = assert_workspace_unchanged(
                "dclint pre-write validation",
                project_root,
                baseline,
                baseline_directories,
            )
            write_status, write_stdout, write_stderr = run_child(
                native_arguments(tool, config_path, fixable_files, True), environment
            )
            assert_config_unchanged(
                config_path, config_snapshot, "controlled private config"
            )
            if source_config_path is not None:
                assert_config_unchanged(
                    source_config_path, source_config_snapshot, "source config"
                )
            after_write, after_write_directories = scan_workspace(project_root)
            write_diff = workspace_diff(
                before_write,
                before_write_directories,
                after_write,
                after_write_directories,
            )
            (
                added,
                removed,
                changed,
                touched,
                added_directories,
                removed_directories,
                touched_directories,
            ) = write_diff
            if (
                added
                or removed
                or touched
                or added_directories
                or removed_directories
                or touched_directories
            ):
                reject(
                    "native fix changed retained workspace topology or metadata outside byte edits: "
                    + workspace_change_summary(write_diff)
                )
            allowed_relatives = {
                selected_relatives[path] for path in fixable_files
            }
            unauthorized = sorted(set(changed) - allowed_relatives)
            if unauthorized:
                reject(
                    "native fix changed files outside the proven fixable subset: "
                    + ", ".join(unauthorized)
                )
            for relative in changed:
                before = before_write[relative]
                after = after_write[relative]
                if (before["dev"], before["ino"], before["mode"]) != (
                    after["dev"],
                    after["ino"],
                    after["mode"],
                ):
                    reject(
                        f"native fix changed file identity or mode while editing bytes: {relative}"
                    )
            if not changed:
                reject("native fix was a no-op for every file with proven fixable diagnostics")

            write_report, remaining_fixable, write_validation = validate_report(
                "fix",
                write_status,
                write_stdout,
                write_stderr,
                fixable_files,
                redactions,
            )
            if remaining_fixable or write_validation:
                reject("native fix did not converge to an unambiguous non-fixable result")

            assert_workspace_unchanged(
                "dclint pre-verification validation",
                project_root,
                after_write,
                after_write_directories,
            )

            verify_status, verify_stdout, verify_stderr = run_child(
                native_arguments(tool, config_path, files, False), environment
            )
            assert_config_unchanged(
                config_path, config_snapshot, "controlled private config"
            )
            if source_config_path is not None:
                assert_config_unchanged(
                    source_config_path, source_config_snapshot, "source config"
                )
            assert_workspace_unchanged(
                "post-fix verification",
                project_root,
                after_write,
                after_write_directories,
            )
            verify_report, verify_fixable, verify_validation = validate_report(
                "post-fix verification",
                verify_status,
                verify_stdout,
                verify_stderr,
                files,
                redactions,
            )
            if verify_fixable or verify_validation:
                reject("authoritative post-fix verification is not converged")
            write_by_path = {item["filePath"]: item for item in write_report}
            verify_by_path = {item["filePath"]: item for item in verify_report}
            if any(write_by_path[path] != verify_by_path[path] for path in fixable_files):
                reject("write-child and authoritative verification reports disagree")
            result = (verify_status, verify_report)
    except AdapterSignal as caught:
        error = ContractError(f"received signal {caught.signum}")
        reported_signal = caught.signum
    except ContractError as caught:
        error = caught
    except BaseException as caught:
        error = caught
    finally:
        cleaning = True
        try:
            child_cleanup_error = stop_child()
            if child_cleanup_error is not None:
                error = append_adapter_error(
                    error, ContractError(f"child cleanup failed: {child_cleanup_error}")
                )
        except BaseException as cleanup_error:
            error = append_adapter_error(
                error, ContractError(f"cannot stop native dclint: {cleanup_error}")
            )
        blocked_mask = None
        rollback_attempted = False
        try:
            if private_config_dir is not None:
                try:
                    shutil.rmtree(private_config_dir)
                except OSError as cleanup_error:
                    error = append_adapter_error(
                        error,
                        ContractError(
                            f"cannot remove private dclint config directory: {cleanup_error}"
                        ),
                    )
            try:
                blocked_mask = signal.pthread_sigmask(signal.SIG_BLOCK, HANDLED_SIGNALS)
            except (OSError, ValueError) as mask_error:
                error = append_adapter_error(
                    error, ContractError(f"cannot block cleanup signals: {mask_error}")
                )

            while True:
                error = apply_pending_signal(error)
                drained = False
                if blocked_mask is not None:
                    error, drained = drain_blocked_signals(error)
                if (
                    error is not None
                    and baseline is not None
                    and baseline_directories is not None
                    and not rollback_attempted
                ):
                    rollback_attempted = True
                    rollback_error = restore_workspace(
                        project_root, baseline, baseline_directories
                    )
                    if rollback_error is not None:
                        error = append_adapter_error(
                            error, ContractError(f"rollback failed: {rollback_error}")
                        )
                    continue
                if not drained:
                    break

            for signum, handler in previous_handlers.items():
                try:
                    signal.signal(signum, handler)
                except (OSError, ValueError) as handler_error:
                    error = append_adapter_error(
                        error,
                        ContractError(f"cannot restore signal handler: {handler_error}"),
                    )

            while True:
                error = apply_pending_signal(error)
                drained = False
                if blocked_mask is not None:
                    error, drained = drain_blocked_signals(error)
                if (
                    error is not None
                    and baseline is not None
                    and baseline_directories is not None
                    and not rollback_attempted
                ):
                    rollback_attempted = True
                    rollback_error = restore_workspace(
                        project_root, baseline, baseline_directories
                    )
                    if rollback_error is not None:
                        error = append_adapter_error(
                            error, ContractError(f"rollback failed: {rollback_error}")
                        )
                    continue
                if not drained:
                    break
        finally:
            # This is a one-shot process. Keep handled signals blocked through
            # diagnostics and exit so cleanup has a deterministic cutoff.
            cleaning = False

    if error is not None:
        raise ContractError(sanitize_private_error(error, private_config_dir))
    if result is None:
        reject("adapter completed without a result")
    status, report = result
    if any(record["messages"] for record in report):
        stable = json.dumps(
            report,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        sys.stdout.buffer.write((stable + "\n").encode("ascii"))
    return status


try:
    raise SystemExit(execute())
except ContractError as error:
    print(f"velvet-glove-dclint: {error}", file=sys.stderr)
    raise SystemExit(2)

